<?php
declare(strict_types=1);

require_once __DIR__ . '/DwBrand.php';

/**
 * Affiliate join: email verify, CRM person/company/relation under the platform brand
 * (PLATFORM_BRAND_CODE in DwConfig), affiliate + channel rows, and attribution id resolve.
 */
class DwAffiliate
{
    /** @var ?string Test-only Host→brand override. Null means use the request host. */
    private static ?string $requestBrandOverride = null;
    // Default affiliate terms (refs #69, #79): generated by termsForSettings() from the program settings and
    // the brand name; the platform's own program can add a legal clause from AFFILIATE_TERMS_* (DwConfig).
    // These are a starting point, not legal advice. Anyone running an affiliate program must have their own
    // lawyer review the terms (default or custom) before use. See docs/affiliates/TERMS.md.

    /** The platform's own brand code (PLATFORM_BRAND_CODE in DwConfig). */
    public static function platformBrand(): string
    {
        return DwConfig::get('PLATFORM_BRAND_CODE');
    }

    /** Default join-page terms for the platform's own program (20% off the first year). */
    public static function defaultTerms(): string
    {
        return self::termsForSettings(['client_discount_percent' => number_format(self::DISCOUNT_PERCENT, 2, '.', ''), 'client_discount_months' => self::DISCOUNT_MONTHS], DwBrand::name(), true);
    }

    public const COOKIE = 'dw_affiliate';
    public const VERIFY_MINUTES = 30;
    public const SESSION_DAYS = 30;
    public const CHANNEL_TYPES = [
        'email_list' => 'Email list',
        'website' => 'Website',
        'tiktok' => 'TikTok',
        'facebook' => 'Facebook',
        'youtube' => 'YouTube',
        'other' => 'Other',
    ];

    public static function newId(PDO $db): string
    {
        for ($i = 0; $i < 8; $i++) {
            $id = Dw::randId();
            if (self::idTaken($db, $id) === false) {
                return $id;
            }
        }
        throw new RuntimeException('DwAffiliate::newId could not allocate a unique id');
    }

    /** Crockford-like alphabet with 0, O, 1, I, and L removed so codes stay unambiguous. */
    public const CODE_ALPHABET = '23456789ABCDEFGHJKMNPQRSTVWXYZ';
    public const AFFILIATE_CODE_PREFIX = 'AFF-';
    public const CHANNEL_CODE_PREFIX = 'CH-';
    public const TRANSFER_CODE_PREFIX = 'XFER-';
    public const CODE_SUFFIX_MIN = 4;
    public const CODE_SUFFIX_MAX = 12;
    public const DEFAULT_COMMISSION_PERCENT = '20.00';
    public const TRANSFER_REASONS = [
        'sale' => 'Sale',
        'inheritance' => 'Inheritance',
        'corporate_transfer' => 'Corporate transfer',
        'other' => 'Other',
    ];

    /**
     * Allocate a human-friendly code (AFF-XXXX or CH-XXXX).
     * Suffix starts at 4 characters, is cryptographically random, retries on
     * collision, and widens (up to 12) if collisions persist.
     */
    public static function newCode(PDO $db, string $kind): string
    {
        if ($kind === 'channel') {
            $prefix = self::CHANNEL_CODE_PREFIX;
        } elseif ($kind === 'affiliate') {
            $prefix = self::AFFILIATE_CODE_PREFIX;
        } elseif ($kind === 'transfer') {
            $prefix = self::TRANSFER_CODE_PREFIX;
        } else {
            throw new InvalidArgumentException('DwAffiliate::newCode: kind must be affiliate, channel, or transfer');
        }
        $max = strlen(self::CODE_ALPHABET) - 1;
        for ($len = self::CODE_SUFFIX_MIN; $len <= self::CODE_SUFFIX_MAX; $len++) {
            for ($i = 0; $i < 8; $i++) {
                $suffix = '';
                for ($j = 0; $j < $len; $j++) {
                    $suffix .= self::CODE_ALPHABET[random_int(0, $max)];
                }
                $code = $prefix . $suffix;
                if (self::codeTaken($db, $code) === false) {
                    return $code;
                }
            }
        }
        throw new RuntimeException('DwAffiliate::newCode could not allocate a unique code');
    }

    public static function normalizeCode(string $code): string
    {
        return strtoupper(trim($code));
    }

    /**
     * Resolve an attribution id or human-friendly code to the affiliate it belongs to.
     * Long ids and codes are accepted, case-insensitive. Main affiliate ids/codes
     * return affiliate_channel_id = null. Channel ids/codes return both.
     */
    public static function resolve(PDO $db, string $id, ?string $brand = null): ?array
    {
        $id = trim($id);
        if ($brand === null) {
            $brand = self::requestBrand($db);
        }
        if ($brand === null || $brand === '') {
            return null;
        }
        if (preg_match('/^[a-f0-9]{50}$/i', $id)) {
            $q = $db->prepare(
                'SELECT a.affiliate_id FROM affiliate a
                  JOIN person p ON p.id = a.person_id
                 WHERE a.affiliate_id = ? AND p.brand = ?'
            );
            $q->execute([$id, $brand]);
            $aid = $q->fetchColumn();
            if (is_string($aid) && $aid !== '') {
                return [
                    'affiliate_id' => $aid,
                    'affiliate_channel_id' => null,
                ];
            }
            $q = $db->prepare(
                'SELECT c.affiliate_channel_id, c.affiliate_id
                   FROM affiliate_channel c
                   JOIN affiliate a ON a.affiliate_id = c.affiliate_id
                   JOIN person p ON p.id = a.person_id
                  WHERE c.affiliate_channel_id = ? AND p.brand = ?'
            );
            $q->execute([$id, $brand]);
            $row = $q->fetch(PDO::FETCH_ASSOC);
            if (!$row) {
                return null;
            }
            return [
                'affiliate_id' => (string)$row['affiliate_id'],
                'affiliate_channel_id' => (string)$row['affiliate_channel_id'],
            ];
        }
        $code = self::normalizeCode($id);
        $alpha = self::CODE_ALPHABET;
        if (preg_match('/^AFF-[' . $alpha . ']{4,12}$/', $code) === 1) {
            $q = $db->prepare(
                'SELECT a.affiliate_id FROM affiliate a
                  JOIN person p ON p.id = a.person_id
                 WHERE a.code = ? AND p.brand = ?'
            );
            $q->execute([$code, $brand]);
            $aid = $q->fetchColumn();
            if (is_string($aid) && $aid !== '') {
                return [
                    'affiliate_id' => $aid,
                    'affiliate_channel_id' => null,
                ];
            }
            return null;
        }
        if (preg_match('/^CH-[' . $alpha . ']{4,12}$/', $code) === 1) {
            $q = $db->prepare(
                'SELECT c.affiliate_channel_id, c.affiliate_id
                   FROM affiliate_channel c
                   JOIN affiliate a ON a.affiliate_id = c.affiliate_id
                   JOIN person p ON p.id = a.person_id
                  WHERE c.code = ? AND p.brand = ?'
            );
            $q->execute([$code, $brand]);
            $row = $q->fetch(PDO::FETCH_ASSOC);
            if (!$row) {
                return null;
            }
            return [
                'affiliate_id' => (string)$row['affiliate_id'],
                'affiliate_channel_id' => (string)$row['affiliate_channel_id'],
            ];
        }
        return null;
    }

    public static function history(PDO $db, string $table, string $id, string $action): int
    {
        if (!$db->inTransaction()) {
            throw new LogicException('DwAffiliate::history must run inside the transaction that changes ' . $table);
        }
        if (!in_array($action, ['INSERT', 'UPDATE', 'DELETE'], true)) {
            throw new InvalidArgumentException('DwAffiliate::history: bad action');
        }
        if ($table === 'affiliate') {
            $sql = 'INSERT INTO affiliate_history (history_id, affiliate_id, code, person_id, company_id, owner_person_id, owner_company_id, commission_rate_override, status, created, updated, action, archived_at)
                    SELECT ?, affiliate_id, code, person_id, company_id, owner_person_id, owner_company_id, commission_rate_override, status, created, updated, ?, NOW()
                    FROM affiliate WHERE affiliate_id = ?';
        } elseif ($table === 'affiliate_channel') {
            $sql = 'INSERT INTO affiliate_channel_history (history_id, affiliate_channel_id, code, affiliate_id, type, handle, created, updated, action, archived_at)
                    SELECT ?, affiliate_channel_id, code, affiliate_id, type, handle, created, updated, ?, NOW()
                    FROM affiliate_channel WHERE affiliate_channel_id = ?';
        } else {
            throw new InvalidArgumentException('DwAffiliate::history: bad table');
        }
        $q = $db->prepare($sql);
        $q->execute([Dw::randId(), $action, $id]);
        return $q->rowCount();
    }

    public static function hashSecret(string $secret): string
    {
        return hash('sha256', $secret);
    }

    public static function confirmCode(): string
    {
        $alphabet = '0123456789abcdefghijklmnopqrstuvwxyz';
        $out = '';
        for ($i = 0; $i < 6; $i++) {
            $out .= $alphabet[random_int(0, 35)];
        }
        return $out;
    }

    public static function normalizeEmail(string $email): string
    {
        return strtolower(trim($email));
    }

    public static function requestVerification(PDO $db, string $email, string $joinUrl): array
    {
        $email = self::normalizeEmail($email);
        if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return ['ok' => false, 'error' => 'a valid email is required'];
        }
        if (strlen($email) > 100) {
            return ['ok' => false, 'error' => 'email is longer than 100 characters'];
        }
        $brand = self::requestBrand($db);
        if ($brand === null) {
            return ['ok' => false, 'error' => 'this site is not set up for the affiliate program'];
        }
        $settings = self::programSettings($db, $brand);
        if (!$settings['program_enabled']) {
            return ['ok' => false, 'error' => 'the affiliate program is not enabled on this site'];
        }
        $token = bin2hex(random_bytes(32));
        $code = self::confirmCode();
        $id = Dw::randId();
        $existing = self::findAffiliateByEmail($db, $email, $brand);
        $db->beginTransaction();
        try {
            $db->prepare('DELETE FROM affiliate_email_challenge WHERE email = ? AND verified_at IS NULL')->execute([$email]);
            $db->prepare(
                'INSERT INTO affiliate_email_challenge (id, email, secret_hash, code_hash, affiliate_id, verified_at, expires, created)
                 VALUES (?, ?, ?, ?, ?, NULL, DATE_ADD(NOW(), INTERVAL ? MINUTE), NOW())'
            )->execute([
                $id,
                $email,
                self::hashSecret($token),
                self::hashSecret(strtolower($code)),
                $existing['affiliate_id'] ?? null,
                self::VERIFY_MINUTES,
            ]);
            $db->commit();
        } catch (Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            return ['ok' => false, 'error' => 'could not start verification'];
        }
        $mailed = self::sendVerificationEmail($email, $token, $code, self::emailContext($db, $brand, $joinUrl, $settings));
        if (!$mailed) {
            return ['ok' => false, 'error' => 'could not send the verification email'];
        }
        // Never return the token or code in the HTTP/JSON response; they go by email only.
        return ['ok' => true, 'mailed' => true];
    }


    /** Strip spaces (and other whitespace) from a pasted verification code or link token. */
    public static function normalizeVerifyInput(string $token): string
    {
        $token = trim($token);
        $stripped = preg_replace('/\s+/', '', $token);
        return is_string($stripped) ? $stripped : $token;
    }

    /** Display form of the 6-character code: one space between each letter, e.g. "n a b a l q". */
    public static function formatVerifyCode(string $code): string
    {
        $code = strtolower(self::normalizeVerifyInput($code));
        return $code === '' ? '' : implode(' ', str_split($code));
    }

    public static function verificationUrl(string $token, ?string $joinUrl = null): string
    {
        $base = is_string($joinUrl) && $joinUrl !== '' ? $joinUrl : 'https://' . DwBrand::appHost() . '/affiliate/join/';
        $base = preg_replace('#/+(?:\?.*)?$#', '', $base) ?? $base;
        return $base . '/?v=' . self::normalizeVerifyInput($token);
    }

    /**
     * HTML + plain-text bodies for the affiliate verification email.
     * The token and code are for the email only; callers must not put them in HTTP JSON.
     *
     * @return array{html:string,text:string,subject:string,verify_url:string}
