        $code = self::normalizeVerifyInput($code);
        $url = self::verificationUrl($token, is_array($ctx) ? ($ctx['join_url'] ?? null) : null);
        $spaced = htmlspecialchars(self::formatVerifyCode($code), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $urlH = htmlspecialchars($url, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $minutes = (int) self::VERIFY_MINUTES;
        $brandName = DwBrand::name();
        $brandLegal = DwBrand::legalName();
        $siteUrl = 'https://' . DwBrand::domain();
        $siteLabel = DwBrand::domain();
        $termsUrl = 'https://' . DwBrand::domain() . '/terms.html';
        $supportEmail = DwBrand::supportEmail();
        $logo = DwBrand::logoUrl();
        $useDwChrome = true;
        $commissionPct = '20';
        $discountPct = '20';
        $discountDuration = 'their first year';
        $programName = 'the ' . DwBrand::name() . ' affiliate program';
        if (is_array($ctx)) {
            $brandName = (string)($ctx['brand_name'] ?? $brandName);
            $brandLegal = (string)($ctx['brand_legal'] ?? $brandLegal);
            $siteUrl = (string)($ctx['site_url'] ?? $siteUrl);
