    public static function sendVerificationEmail(string $email, string $token, string $code, ?array $ctx = null): bool
    {
        $parts = self::verificationEmail($token, $code, $ctx);
        $b = static fn (string $s): string => rtrim(chunk_split(base64_encode($s), 76, "\r\n"));
        $alt = 'alt_' . bin2hex(random_bytes(8));
        $htmlPart = "Content-Type: text/html; charset=utf-8\r\nContent-Transfer-Encoding: base64\r\n\r\n" . $b($parts['html']) . "\r\n";
        $mime = "MIME-Version: 1.0\r\nAuto-Submitted: auto-generated\r\nContent-Type: multipart/alternative; boundary=\"{$alt}\"\r\n\r\n"
            . "--{$alt}\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Transfer-Encoding: base64\r\n\r\n" . $b($parts['text']) . "\r\n"
            . "--{$alt}\r\n" . $htmlPart . "--{$alt}--\r\n";
        return Dw::sendMime($email, $parts['subject'], $mime);
    }

    public static function consumeVerification(PDO $db, string $token): ?array
    {
        $token = self::normalizeVerifyInput($token);
        $hashCol = null;
        $hash = '';
        if (preg_match('/^[a-f0-9]{64}$/i', $token)) {
            $hashCol = 'secret_hash';
            $hash = self::hashSecret($token);
        } elseif (preg_match('/^[0-9a-z]{6}$/i', $token)) {
            $hashCol = 'code_hash';
            $hash = self::hashSecret(strtolower($token));
        } else {
            return null;
        }
        $ownTx = !$db->inTransaction();
        if ($ownTx) {
            $db->beginTransaction();
        }
        try {
            $q = $db->prepare(
                'SELECT id, email, affiliate_id FROM affiliate_email_challenge
                 WHERE ' . $hashCol . ' = ? AND verified_at IS NULL AND expires > NOW()
                 FOR UPDATE'
            );
            $q->execute([$hash]);
            $row = $q->fetch(PDO::FETCH_ASSOC);
            if (!$row) {
                if ($ownTx && $db->inTransaction()) {
                    $db->rollBack();
                }
                return null;
            }
            $sessionId = Dw::randId();
            $sessionSecret = bin2hex(random_bytes(32));
            $db->prepare('DELETE FROM affiliate_email_challenge WHERE id = ?')->execute([$row['id']]);
            $db->prepare(
                'INSERT INTO affiliate_email_challenge (id, email, secret_hash, code_hash, affiliate_id, verified_at, expires, created)
                 VALUES (?, ?, ?, ?, ?, NOW(), DATE_ADD(NOW(), INTERVAL ? DAY), NOW())'
            )->execute([
                $sessionId,
                $row['email'],
                self::hashSecret($sessionSecret),
                self::hashSecret(Dw::randId()),
                $row['affiliate_id'] !== null && $row['affiliate_id'] !== '' ? $row['affiliate_id'] : null,
                self::SESSION_DAYS,
            ]);
            if ($ownTx) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($ownTx && $db->inTransaction()) {
                $db->rollBack();
            }
            return null;
        }
        return [
            'cookie' => $sessionId . '.' . $sessionSecret,
            'email' => (string)$row['email'],
        ];
    }

    public static function sessionFromCookie(PDO $db, string $cookie): ?array
    {
        $cookie = trim($cookie);
        $dot = strpos($cookie, '.');
        if ($dot === false) {
            return null;
        }
        $id = substr($cookie, 0, $dot);
        $secret = substr($cookie, $dot + 1);
        if (!preg_match('/^[a-f0-9]{50}$/i', $id) || !preg_match('/^[a-f0-9]{64}$/i', $secret)) {
            return null;
        }
        $q = $db->prepare(
            'SELECT id, email, affiliate_id, verified_at, expires
             FROM affiliate_email_challenge
             WHERE id = ? AND verified_at IS NOT NULL AND expires > NOW()'
        );
        $q->execute([$id]);
        $row = $q->fetch(PDO::FETCH_ASSOC);
        if (!$row) {
            return null;
        }
        $q = $db->prepare('SELECT secret_hash FROM affiliate_email_challenge WHERE id = ?');
        $q->execute([$id]);
        $hash = (string)$q->fetchColumn();
        if ($hash === '' || !hash_equals($hash, self::hashSecret($secret))) {
            return null;
        }
        return [
            'id' => (string)$row['id'],
            'email' => (string)$row['email'],
            'affiliate_id' => $row['affiliate_id'] !== null && $row['affiliate_id'] !== '' ? (string)$row['affiliate_id'] : null,
        ];
    }

    public static function setSessionCookie(string $value): void
    {
        $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
        setcookie(self::COOKIE, $value, [
            'expires' => time() + (self::SESSION_DAYS * 86400),
            'path' => '/affiliate/',
            'secure' => $secure,
            'httponly' => true,
            'samesite' => 'Lax',
        ]);
    }

    public static function clearSessionCookie(): void
    {
        setcookie(self::COOKIE, '', [
            'expires' => time() - 3600,
            'path' => '/affiliate/',
            'httponly' => true,
            'samesite' => 'Lax',
        ]);
    }

    public static function findAffiliateByEmail(PDO $db, string $email, ?string $brand = null): ?array
    {
        $email = self::normalizeEmail($email);
        $brand = $brand ?? self::requestBrand($db);
        if ($brand === null) {
            return null;
        }
        $q = $db->prepare(
            'SELECT a.affiliate_id, a.person_id, a.company_id, a.status
             FROM email e
             INNER JOIN affiliate a ON a.person_id = e.owner_id
             WHERE e.owner_type = \'PRSN\' AND e.brand = ? AND LOWER(e.email) = ?
             LIMIT 1'
        );
        $q->execute([$brand, $email]);
        $row = $q->fetch(PDO::FETCH_ASSOC);
        return $row ?: null;
    }

    public static function loadPageState(PDO $db, array $session): array
    {
        $email = $session['email'];
        $affiliate = null;
        $person = ['first_name' => '', 'last_name' => ''];
        $companyName = '';
        $channels = [];
        $aid = $session['affiliate_id'];
        if ($aid === null) {
            $found = self::findAffiliateByEmail($db, $email);
            if ($found) {
                $aid = $found['affiliate_id'];
            }
        }
        if ($aid !== null) {
            $q = $db->prepare(
                'SELECT a.affiliate_id, a.code, a.person_id, a.company_id,
                        a.owner_person_id, a.owner_company_id, a.commission_rate_override, a.status,
                        p.first_name, p.last_name, c.company_name
                 FROM affiliate a
                 INNER JOIN person p ON p.id = a.person_id
                 LEFT JOIN company c ON c.id = a.company_id
                 WHERE a.affiliate_id = ?'
            );
            $q->execute([$aid]);
            $affiliate = $q->fetch(PDO::FETCH_ASSOC) ?: null;
            if ($affiliate) {
                $person = [
                    'first_name' => (string)$affiliate['first_name'],
                    'last_name' => (string)$affiliate['last_name'],
                ];
                $companyName = (string)($affiliate['company_name'] ?? '');
                $cq = $db->prepare(
                    'SELECT affiliate_channel_id, code, type, handle
                     FROM affiliate_channel
                     WHERE affiliate_id = ?
                     ORDER BY created, affiliate_channel_id'
                );
                $cq->execute([$aid]);
                $channels = $cq->fetchAll(PDO::FETCH_ASSOC) ?: [];
            }
        }
        return [
            'email' => $email,
            'affiliate' => $affiliate,
            'first_name' => $person['first_name'],
            'last_name' => $person['last_name'],
            'company_name' => $companyName,
            'channels' => $channels,
        ];
    }

    /**
     * Create or update CRM person/company/relation and the affiliate row.
     * Never duplicates an existing person or company for this verified email.
     */
    public static function saveProfile(PDO $db, array $session, string $firstName, string $lastName, string $companyName): array
    {
        $firstName = trim($firstName);
        $lastName = trim($lastName);
        $companyName = trim($companyName);
        if ($firstName === '' || $lastName === '') {
            return ['ok' => false, 'error' => 'first name and last name are required'];
        }
        if (strlen($firstName) > 100 || strlen($lastName) > 100) {
            return ['ok' => false, 'error' => 'name is longer than 100 characters'];
        }
        if (strlen($companyName) > 100) {
            return ['ok' => false, 'error' => 'company name is longer than 100 characters'];
        }
        $email = self::normalizeEmail($session['email']);
        $brand = self::requestBrand($db);
        if ($brand === null) {
            return ['ok' => false, 'error' => 'this site is not set up for the affiliate program'];
        }
        $settings = self::programSettings($db, $brand);
        if (!$settings['program_enabled']) {
            return ['ok' => false, 'error' => 'the affiliate program is not enabled on this site'];
        }
        $loginGranted = false;
        $db->beginTransaction();
        try {
            $personId = self::upsertPerson($db, $email, $firstName, $lastName, $brand);
            $companyId = self::upsertCompany($db, $personId, $companyName, $session['affiliate_id'] ?? null, $brand);
            $affiliateId = self::upsertAffiliate($db, $personId, $companyId, $session['affiliate_id'] ?? null);
            $db->prepare('UPDATE affiliate_email_challenge SET affiliate_id = ? WHERE id = ?')->execute([$affiliateId, $session['id']]);
            $loginGranted = self::grantJoinLogin($db, $personId, $brand);
            $db->commit();
        } catch (DwAffiliateLimit $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            return ['ok' => false, 'error' => $e->getMessage(), 'gate' => $e->gate];
        } catch (Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            return ['ok' => false, 'error' => 'could not save your information'];
        }
        if ($loginGranted && method_exists('Dw', 'refreshSessionRights')) {
            Dw::refreshSessionRights($db, $personId, $brand);
        }
        return ['ok' => true, 'affiliate_id' => $affiliateId, 'person_id' => $personId, 'company_id' => $companyId, 'login_granted' => $loginGranted];
    }

    /**
     * Completing the join (verified email + save_profile) grants LOGIN READ on the brand so the affiliate can
     * sign in with a magic link and connect ChatGPT with affiliate:join (refs #74, 2026-11-22).
     * Same rights path as account setup: data_access + data_access_history INSERT. No-op when the person
     * already has any LOGIN right or SUPER_ADMIN. Runs inside the caller's transaction.
     */
    public static function grantJoinLogin(PDO $db, string $personId, string $brand, ?string $actorPersonId = null): bool
    {
        $ex = $db->prepare("SELECT 1 FROM data_access WHERE person_id = ? AND brand = ? AND (module_name = 'LOGIN' OR right_name = 'SUPER_ADMIN') LIMIT 1");
        $ex->execute([$personId, $brand]);
        if ($ex->fetchColumn() !== false) {
            return false;
        }
        $id = Dw::randId();
        $db->prepare("INSERT INTO data_access (id, person_id, brand, created, created_by_person_id, right_name, module_name) VALUES (?, ?, ?, NOW(), ?, 'READ', 'LOGIN')")
            ->execute([$id, $personId, $brand, $actorPersonId ?? $personId]);
        $db->prepare("INSERT INTO data_access_history (history_id, id, person_id, brand, created, created_by_person_id, right_name, module_name, action, archived_at)
                      SELECT ?, id, person_id, brand, created, created_by_person_id, right_name, module_name, 'INSERT', NOW() FROM data_access WHERE id = ?")
            ->execute([Dw::randId(), $id]);
        return true;
    }

    /**
     * Backfill for affiliates who joined before the join flow granted LOGIN (refs #77): every active affiliate of the
     * brand without a LOGIN right or SUPER_ADMIN gets READ/LOGIN through grantJoinLogin (data_access + history),
     * recorded as granted by the staff person. Idempotent. The caller must be a SUPER_ADMIN of the brand.
     * @return array{ok:bool,error?:string,checked?:int,granted?:int}
     */
    public static function backfillJoinLogin(PDO $db, string $brand, string $actorPersonId): array
    {
        if (!class_exists('DwPermissions', false)) {
            require_once __DIR__ . '/DwPermissions.php';
        }
        if (!DwPermissions::isSuperAdmin($actorPersonId, $brand)) {
            return ['ok' => false, 'http' => 403, 'error' => 'only a SUPER_ADMIN of this brand can grant sign-in rights'];
        }
        $q = $db->prepare("SELECT DISTINCT a.person_id FROM affiliate a JOIN person p ON p.id = a.person_id WHERE p.brand = ? AND a.status = 'active'");
        $q->execute([$brand]);
        $people = $q->fetchAll(PDO::FETCH_COLUMN);
        $granted = [];
        foreach ($people as $pid) {
            $db->beginTransaction();
            try {
                if (self::grantJoinLogin($db, (string)$pid, $brand, $actorPersonId)) {
                    $granted[] = (string)$pid;
                }
                $db->commit();
            } catch (Throwable $e) {
                if ($db->inTransaction()) {
                    $db->rollBack();
                }
                error_log('affiliate backfill login: ' . $e->getMessage());
                return ['ok' => false, 'error' => 'could not grant sign-in rights to every affiliate; run it again', 'checked' => count($people), 'granted' => count($granted)];
            }
        }
        foreach ($granted as $pid) {
            if (method_exists('Dw', 'refreshSessionRights')) {
                Dw::refreshSessionRights($db, $pid, $brand);
            }
        }
        return ['ok' => true, 'checked' => count($people), 'granted' => count($granted)];
    }

    public static function addChannel(PDO $db, string $affiliateId, string $type, string $handle): array
    {
        $type = self::validType($type);
        $handle = self::validHandle($handle);
        if ($type === null) {
            return ['ok' => false, 'error' => 'choose a channel type'];
        }
        if ($handle === null) {
            return ['ok' => false, 'error' => 'enter a channel id, handle, or URL'];
        }
        $db->beginTransaction();
        try {
            if (!self::ownAffiliate($db, $affiliateId)) {
                $db->rollBack();
                return ['ok' => false, 'error' => 'affiliate not found'];
            }
            $id = self::newId($db);
            $code = self::newCode($db, 'channel');
            $db->prepare(
                'INSERT INTO affiliate_channel (affiliate_channel_id, code, affiliate_id, type, handle, created, updated)
                 VALUES (?, ?, ?, ?, ?, NOW(), NOW())'
            )->execute([$id, $code, $affiliateId, $type, $handle]);
            self::history($db, 'affiliate_channel', $id, 'INSERT');
            $db->commit();
        } catch (Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            return ['ok' => false, 'error' => 'could not add the channel'];
        }
        return ['ok' => true, 'affiliate_channel_id' => $id, 'channel_code' => $code];
    }

    public static function updateChannel(PDO $db, string $affiliateId, string $channelId, string $type, string $handle): array
    {
        $type = self::validType($type);
        $handle = self::validHandle($handle);
        if ($type === null) {
            return ['ok' => false, 'error' => 'choose a channel type'];
        }
        if ($handle === null) {
            return ['ok' => false, 'error' => 'enter a channel id, handle, or URL'];
        }
        $db->beginTransaction();
        try {
            $q = $db->prepare('SELECT affiliate_channel_id FROM affiliate_channel WHERE affiliate_channel_id = ? AND affiliate_id = ? FOR UPDATE');
            $q->execute([$channelId, $affiliateId]);
            if ($q->fetchColumn() === false) {
                $db->rollBack();
                return ['ok' => false, 'error' => 'channel not found'];
            }
            self::history($db, 'affiliate_channel', $channelId, 'UPDATE');
            $db->prepare(
                'UPDATE affiliate_channel SET type = ?, handle = ?, updated = NOW()
                 WHERE affiliate_channel_id = ? AND affiliate_id = ?'
            )->execute([$type, $handle, $channelId, $affiliateId]);
            $db->commit();
        } catch (Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            return ['ok' => false, 'error' => 'could not update the channel'];
        }
        return ['ok' => true, 'affiliate_channel_id' => $channelId];
    }

    public static function removeChannel(PDO $db, string $affiliateId, string $channelId): array
    {
        $db->beginTransaction();
        try {
            $q = $db->prepare('SELECT affiliate_channel_id FROM affiliate_channel WHERE affiliate_channel_id = ? AND affiliate_id = ? FOR UPDATE');
            $q->execute([$channelId, $affiliateId]);
            if ($q->fetchColumn() === false) {
                $db->rollBack();
                return ['ok' => false, 'error' => 'channel not found'];
            }
            self::history($db, 'affiliate_channel', $channelId, 'DELETE');
            $db->prepare('DELETE FROM affiliate_channel WHERE affiliate_channel_id = ? AND affiliate_id = ?')->execute([$channelId, $affiliateId]);
            $db->commit();
        } catch (Throwable $e) {
            if ($db->inTransaction()) {
                $db->rollBack();
            }
            return ['ok' => false, 'error' => 'could not remove the channel'];
        }
        return ['ok' => true, 'affiliate_channel_id' => $channelId];
    }

    private static function upsertPerson(PDO $db, string $email, string $firstName, string $lastName, string $brand): string
    {
        $q = $db->prepare(
            'SELECT id, owner_id FROM email
             WHERE owner_type = \'PRSN\' AND brand = ? AND LOWER(email) = ?
             LIMIT 1 FOR UPDATE'
        );
        $q->execute([$brand, $email]);
        $row = $q->fetch(PDO::FETCH_ASSOC);
        if ($row) {
            $personId = (string)$row['owner_id'];
            $own = $db->prepare('SELECT id FROM person WHERE id = ? AND brand = ? FOR UPDATE');
            $own->execute([$personId, $brand]);
            if ($own->fetchColumn() === false) {
                throw new RuntimeException('email points at a missing person');
            }
            Dw::history($db, 'person', $personId, 'UPDATE');
            $db->prepare('UPDATE person SET first_name = ?, last_name = ? WHERE id = ? AND brand = ?')
                ->execute([$firstName, $lastName, $personId, $brand]);
            return $personId;
        }
        $personId = Dw::randId();
        $emailId = Dw::randId();
        $db->prepare('INSERT INTO person (id, first_name, last_name, created, brand) VALUES (?, ?, ?, NOW(), ?)')
            ->execute([$personId, $firstName, $lastName, $brand]);
        Dw::history($db, 'person', $personId, 'INSERT');
        $db->prepare(
            'INSERT INTO email (id, email, owner_id, owner_type, created, created_by, brand)
             VALUES (?, ?, ?, \'PRSN\', NOW(), ?, ?)'
        )->execute([$emailId, $email, $personId, $personId, $brand]);
        Dw::history($db, 'email', $emailId, 'INSERT');
        return $personId;
    }

    private static function upsertCompany(PDO $db, string $personId, string $companyName, ?string $affiliateId, string $brand): ?string
    {
        $existingCompanyId = null;
        if ($affiliateId) {
            $q = $db->prepare('SELECT company_id FROM affiliate WHERE affiliate_id = ? FOR UPDATE');
            $q->execute([$affiliateId]);
            $existingCompanyId = $q->fetchColumn();
            $existingCompanyId = is_string($existingCompanyId) && $existingCompanyId !== '' ? $existingCompanyId : null;
        }
        if ($existingCompanyId === null) {
            $q = $db->prepare(
                'SELECT r.company FROM relation r
                 WHERE r.person_id = ? AND r.brand = ?
                 ORDER BY r.created_on DESC
                 LIMIT 1 FOR UPDATE'
            );
            $q->execute([$personId, $brand]);
            $rel = $q->fetchColumn();
            $existingCompanyId = is_string($rel) && $rel !== '' ? $rel : null;
        }
        if ($companyName === '') {
            return $existingCompanyId;
        }
        if ($existingCompanyId !== null) {
            $own = $db->prepare('SELECT id FROM company WHERE id = ? AND brand = ? FOR UPDATE');
            $own->execute([$existingCompanyId, $brand]);
            if ($own->fetchColumn() === false) {
                $existingCompanyId = null;
            }
        }
        if ($existingCompanyId !== null) {
            Dw::history($db, 'company', $existingCompanyId, 'UPDATE');
            $db->prepare('UPDATE company SET company_name = ? WHERE id = ? AND brand = ?')
                ->execute([$companyName, $existingCompanyId, $brand]);
            self::ensureRelation($db, $personId, $existingCompanyId, $brand);
            return $existingCompanyId;
        }
        $companyId = Dw::randId();
        $db->prepare('INSERT INTO company (id, company_name, brand) VALUES (?, ?, ?)')
            ->execute([$companyId, $companyName, $brand]);
        Dw::history($db, 'company', $companyId, 'INSERT');
        self::ensureRelation($db, $personId, $companyId, $brand);
        return $companyId;
    }

    private static function ensureRelation(PDO $db, string $personId, string $companyId, ?string $brand = null): void
    {
        $brand = $brand ?? self::requestBrand($db);
        if ($brand === null || $brand === '') {
            throw new RuntimeException('DwAffiliate::ensureRelation: no brand for this request');
        }
        $exists = $db->prepare('SELECT id FROM relation WHERE person_id = ? AND company = ? AND brand = ? LIMIT 1');
        $exists->execute([$personId, $companyId, $brand]);
        if ($exists->fetchColumn() !== false) {
            return;
        }
        $id = Dw::randId();
        $db->prepare(
            'INSERT INTO relation (id, person_id, company, created_on, created_by, brand)
             VALUES (?, ?, ?, NOW(), ?, ?)'
        )->execute([$id, $personId, $companyId, $personId, $brand]);
        $db->prepare(
            'INSERT INTO relation_history (history_id, id, person_id, company, created_on, created_by, brand, action)
             SELECT ?, id, person_id, company, created_on, created_by, brand, ? FROM relation WHERE id = ?'
        )->execute([Dw::randId(), 'INSERT', $id]);
    }

    private static function upsertAffiliate(PDO $db, string $personId, ?string $companyId, ?string $knownId): string
    {
        $brand = self::brandForPerson($db, $personId);
        $q = $db->prepare('SELECT affiliate_id, status FROM affiliate WHERE person_id = ? FOR UPDATE');
        $q->execute([$personId]);
        $existing = $q->fetch(PDO::FETCH_ASSOC);
        if (is_array($existing) && is_string($existing['affiliate_id']) && $existing['affiliate_id'] !== '') {
            $id = $existing['affiliate_id'];
            $wasActive = (string)($existing['status'] ?? '') === 'active';
            if (!$wasActive) {
                $gate = self::canAddAffiliate($db, $brand, true);
                if (!$gate['can_add']) {
                    throw new DwAffiliateLimit($gate['notice'], $gate);
                }
            }
            self::history($db, 'affiliate', $id, 'UPDATE');
            // If the right has not been transferred, keep the owner company in sync with the profile company.
            $db->prepare(
                'UPDATE affiliate SET company_id = ?, status = \'active\', updated = NOW(),
                        owner_company_id = IF(owner_person_id = person_id, ?, owner_company_id)
                  WHERE affiliate_id = ?'
            )->execute([$companyId, $companyId, $id]);
            return $id;
        }
        $gate = self::canAddAffiliate($db, $brand, true);
        if (!$gate['can_add']) {
            throw new DwAffiliateLimit($gate['notice'], $gate);
        }
        $id = $knownId && preg_match('/^[a-f0-9]{50}$/i', $knownId) && self::idTaken($db, $knownId) === false
            ? $knownId
            : self::newId($db);
        $code = self::newCode($db, 'affiliate');
        $db->prepare(
            'INSERT INTO affiliate (affiliate_id, code, person_id, company_id, owner_person_id, owner_company_id, commission_rate_override, status, created, updated)
             VALUES (?, ?, ?, ?, ?, ?, NULL, \'active\', NOW(), NOW())'
        )->execute([$id, $code, $personId, $companyId, $personId, $companyId]);
        self::history($db, 'affiliate', $id, 'INSERT');
        return $id;
    }

    private static function brandForPerson(PDO $db, string $personId): string
    {
        $q = $db->prepare('SELECT brand FROM person WHERE id = ?');
        $q->execute([$personId]);
        $b = (string)($q->fetchColumn() ?: '');
        if (preg_match('/^[A-Za-z0-9]{1,10}$/', $b) === 1) {
            return $b;
        }
        return '';
    }

    private static function ownAffiliate(PDO $db, string $affiliateId): bool
    {
        $q = $db->prepare('SELECT affiliate_id FROM affiliate WHERE affiliate_id = ?');
        $q->execute([$affiliateId]);
        return $q->fetchColumn() !== false;
    }

    private static function idTaken(PDO $db, string $id): bool
    {
        $q = $db->prepare('SELECT affiliate_id FROM affiliate WHERE affiliate_id = ?');
        $q->execute([$id]);
        if ($q->fetchColumn() !== false) {
            return true;
        }
        $q = $db->prepare('SELECT affiliate_channel_id FROM affiliate_channel WHERE affiliate_channel_id = ?');
        $q->execute([$id]);
        return $q->fetchColumn() !== false;
    }

    private static function codeTaken(PDO $db, string $code): bool
    {
        $code = self::normalizeCode($code);
        $q = $db->prepare('SELECT affiliate_id FROM affiliate WHERE code = ?');
        $q->execute([$code]);
        if ($q->fetchColumn() !== false) {
            return true;
        }
        $q = $db->prepare('SELECT affiliate_channel_id FROM affiliate_channel WHERE code = ?');
        $q->execute([$code]);
        if ($q->fetchColumn() !== false) {
            return true;
        }
        $q = $db->prepare('SELECT id FROM affiliate_ownership_transfer WHERE code = ?');
        $q->execute([$code]);
        return $q->fetchColumn() !== false;
    }

    private static function validType(string $type): ?string
    {
        $type = trim($type);
        return array_key_exists($type, self::CHANNEL_TYPES) ? $type : null;
    }

    private static function validHandle(string $handle): ?string
    {
        $handle = trim($handle);
        if ($handle === '' || strlen($handle) > 255) {
            return null;
        }
        if (preg_match('/[\r\n\0]/', $handle)) {
            return null;
        }
        return $handle;
    }

    private static function joinUrl(string $joinUrl): string
    {
        $joinUrl = trim($joinUrl);
        if ($joinUrl === '' || !preg_match('#^https?://#i', $joinUrl)) {
            return '/affiliate/join/';
        }
        return rtrim($joinUrl, '/');
    }

    public const REF_COOKIE = 'dw_ref';
    public const REF_WINDOW_DAYS = 90;
    public const KEEP_REF_SCRIPT = '<script src="/affiliate/keep-ref.js" defer></script>';
    private const REF_SALT_FILE = '/var/lib/app/data/affiliate-referral-salt';

    /**
     * First-touch, 90-day attribution. If ?ref= / ?aff= (or a POST field) is a
     * known code, record a referral and set a first-party cookie. A later
     * different code during the window is stored for analytics but does not
     * replace the cookie. Never throws; never stores a raw IP.
     *
     * @return array{referral_id:string,affiliate_id:string,code:string,visitor_token:string}|null
     */
    public static function captureReferralFromRequest(PDO $db, string $sourceType = 'url_param', ?array $jsonBody = null): ?array
    {
        try {
            $sourceType = in_array($sourceType, ['url_param', 'link', 'coupon', 'manual'], true)
                ? $sourceType
                : 'url_param';
            $brand = self::requestBrand($db);
            if ($brand === null) {
                return null;
            }
            $settings = self::programSettings($db, $brand);
            if (!$settings['program_enabled']) {
                return null;
            }
            $incoming = self::intakeCode($jsonBody);
            $cookie = self::parseRefCookie((string)($_COOKIE[self::REF_COOKIE] ?? ''));
            $active = $cookie !== null && self::referralInWindow($db, $cookie['referral_id'], $brand);
            if ($active) {
                if ($incoming !== null && $incoming !== $cookie['code']) {
                    self::insertReferral($db, $incoming, $cookie['visitor_token'], $sourceType);
                } elseif ($incoming !== null) {
                    self::touchReferral($db, $cookie['referral_id']);
                }
                return $cookie;
            }
            if ($incoming === null) {
                return null;
            }
            $token = ($cookie['visitor_token'] ?? '') !== ''
                ? $cookie['visitor_token']
                : bin2hex(random_bytes(16));
            $row = self::insertReferral($db, $incoming, $token, $sourceType);
            if ($row === null) {
                return null;
            }
            self::setRefCookie($row['visitor_token'], $row['code'], $row['referral_id']);
            return $row;
        } catch (Throwable $e) {
            return null;
        }
    }

    /**
     * Credit the first-touch referral in the cookie, once. Safe to call from
     * an existing transaction or on its own. No-ops when there is no cookie
     * or the referral was already converted.
     *
     * @param array{person_id:?string,company_id:?string,reference_type:string,reference_id:string} $conversion
     */
    public static function attributeConversionFromRequest(PDO $db, array $conversion): bool
    {
        try {
            $cookie = self::parseRefCookie((string)($_COOKIE[self::REF_COOKIE] ?? ''));
            if ($cookie === null) {
                return false;
            }
            $type = (string)($conversion['reference_type'] ?? '');
            if (!in_array($type, ['signup', 'order', 'subscription'], true)) {
                return false;
            }
            $refId = trim((string)($conversion['reference_id'] ?? ''));
            if ($refId === '' || !preg_match('/^[a-f0-9]{50}$/i', $refId)) {
                return false;
            }
            $personId = self::optionalId($conversion['person_id'] ?? null);
            $companyId = self::optionalId($conversion['company_id'] ?? null);
            $ownTx = !$db->inTransaction();
            if ($ownTx) {
                $db->beginTransaction();
            }
            try {
                $q = $db->prepare('SELECT id, converted_at FROM affiliate_referral WHERE id = ? FOR UPDATE');
                $q->execute([$cookie['referral_id']]);
                $row = $q->fetch(PDO::FETCH_ASSOC);
                if (!$row || $row['converted_at'] !== null) {
                    if ($ownTx) {
                        $db->rollBack();
                    }
                    return false;
                }
                Dw::history($db, 'affiliate_referral', $cookie['referral_id'], 'UPDATE');
                $db->prepare(
                    'UPDATE affiliate_referral
                        SET converted_person_id = ?, converted_company_id = ?,
                            converted_reference_type = ?, converted_reference_id = ?,
                            converted_at = NOW(), last_seen = NOW(), updated = NOW()
                      WHERE id = ? AND converted_at IS NULL'
                )->execute([$personId, $companyId, $type, $refId, $cookie['referral_id']]);
                if ($ownTx) {
                    $db->commit();
                }
            } catch (Throwable $e) {
                if ($ownTx && $db->inTransaction()) {
                    $db->rollBack();
                }
                throw $e;
            }
            return true;
        } catch (Throwable $e) {
            return false;
        }
    }

    public static function injectKeepRefScript(string $html): string
    {
        if (str_contains($html, '/affiliate/keep-ref.js') || str_contains($html, '/affiliates/keep-ref.js')) {
            return $html;
        }
        $tag = self::KEEP_REF_SCRIPT;
        $pos = strripos($html, '</body>');
        return $pos === false ? $html . $tag : substr_replace($html, $tag . "\n", $pos, 0);
    }

    /**
     * Explicit ref intake. Precedence: X-DW-Ref header, JSON body (ref/aff),
     * POST, GET, then $_REQUEST. A valid explicit value is a new "touch"
     * (a referral row may be recorded). The dw_ref cookie is not an explicit
     * intake source; it only holds first-touch attribution.
     */
    public static function intakeCode(?array $jsonBody = null): ?string
    {
        $candidates = [];
        $header = trim((string)($_SERVER['HTTP_X_DW_REF'] ?? ''));
        if ($header !== '') {
            $candidates[] = $header;
        }
        $body = $jsonBody;
        if ($body === null) {
            $ctype = (string)($_SERVER['CONTENT_TYPE'] ?? $_SERVER['HTTP_CONTENT_TYPE'] ?? '');
            if (str_contains(strtolower($ctype), 'application/json')) {
                $rawJson = file_get_contents('php://input') ?: '';
                if ($rawJson !== '') {
                    $decoded = json_decode($rawJson, true);
                    if (is_array($decoded)) {
                        $body = $decoded;
                    }
                }
            }
        }
        if (is_array($body)) {
            foreach (['ref', 'aff'] as $key) {
                if (isset($body[$key]) && is_string($body[$key]) && trim($body[$key]) !== '') {
                    $candidates[] = $body[$key];
                }
            }
        }
        foreach (['ref', 'aff'] as $key) {
            if (isset($_POST[$key]) && is_string($_POST[$key]) && trim($_POST[$key]) !== '') {
                $candidates[] = $_POST[$key];
            }
        }
        foreach (['ref', 'aff'] as $key) {
            if (isset($_GET[$key]) && is_string($_GET[$key]) && trim($_GET[$key]) !== '') {
                $candidates[] = $_GET[$key];
            }
        }
        foreach (['ref', 'aff'] as $key) {
            if (isset($_REQUEST[$key]) && is_string($_REQUEST[$key]) && trim($_REQUEST[$key]) !== '') {
                $candidates[] = $_REQUEST[$key];
            }
        }
        $alpha = self::CODE_ALPHABET;
        foreach ($candidates as $raw) {
            $code = self::normalizeCode((string)$raw);
            if (preg_match('/^(AFF|CH)-[' . $alpha . ']{4,12}$/', $code) === 1) {
                return $code;
            }
        }
        return null;
    }

    private static function parseRefCookie(string $raw): ?array
    {
        $raw = trim($raw);
        if ($raw === '') {
            return null;
        }
        $parts = explode('.', $raw);
        if (count($parts) < 4 || $parts[0] !== 'v1') {
            return null;
        }
        $token = $parts[1];
        $code = self::normalizeCode($parts[2]);
        $referralId = $parts[3];
        $alpha = self::CODE_ALPHABET;
        if (!preg_match('/^[a-f0-9]{32}$/i', $token)) {
            return null;
        }
        if (preg_match('/^(AFF|CH)-[' . $alpha . ']{4,12}$/', $code) !== 1) {
            return null;
        }
        if (!preg_match('/^[a-f0-9]{50}$/i', $referralId)) {
            return null;
        }
        return [
            'referral_id' => $referralId,
            'affiliate_id' => '',
            'code' => $code,
            'visitor_token' => strtolower($token),
        ];
    }

    private static function referralInWindow(PDO $db, string $referralId, ?string $brand = null): bool
    {
        $brand = $brand ?? self::requestBrand($db);
        if ($brand === null || $brand === '') {
            return false;
        }
        $q = $db->prepare(
            'SELECT r.affiliate_id
               FROM affiliate_referral r
               JOIN affiliate a ON a.affiliate_id = r.affiliate_id
               JOIN person p ON p.id = a.person_id
              WHERE r.id = ? AND p.brand = ? AND r.first_seen >= DATE_SUB(NOW(), INTERVAL ? DAY)'
        );
        $q->execute([$referralId, $brand, self::REF_WINDOW_DAYS]);
        return $q->fetchColumn() !== false;
    }

    /**
     * @return array{referral_id:string,affiliate_id:string,code:string,visitor_token:string}|null
     */
    private static function insertReferral(PDO $db, string $code, string $visitorToken, string $sourceType): ?array
    {
        $resolved = self::resolve($db, $code);
        if ($resolved === null) {
            return null;
        }
        $id = Dw::randId();
        $ownTx = !$db->inTransaction();
        if ($ownTx) {
            $db->beginTransaction();
        }
        try {
            $percent = self::resolvedCommissionPercent($db, $resolved['affiliate_id']);
            $db->prepare(
                'INSERT INTO affiliate_referral (
                    id, affiliate_id, affiliate_channel_id, code, source_type, commission_percent,
                    landing_url, referrer, utm_source, utm_medium, utm_campaign,
                    utm_term, utm_content, visitor_token, ip_hash, user_agent,
                    first_seen, last_seen, created, updated
                 ) VALUES (
                    ?, ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    NOW(), NOW(), NOW(), NOW()
                 )'
            )->execute([
                $id,
                $resolved['affiliate_id'],
                $resolved['affiliate_channel_id'],
                $code,
                $sourceType,
                $percent,
                self::requestLandingUrl(),
                self::requestReferrer(),
                self::utmField('utm_source'),
                self::utmField('utm_medium'),
                self::utmField('utm_campaign'),
                self::utmField('utm_term'),
                self::utmField('utm_content'),
                $visitorToken,
                self::ipHash(self::requestIp()),
                self::requestUserAgent(),
            ]);
            Dw::history($db, 'affiliate_referral', $id, 'INSERT');
            if ($ownTx) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($ownTx && $db->inTransaction()) {
                $db->rollBack();
            }
            throw $e;
        }
        return [
            'referral_id' => $id,
            'affiliate_id' => $resolved['affiliate_id'],
            'code' => $code,
            'visitor_token' => $visitorToken,
        ];
    }

    private static function touchReferral(PDO $db, string $referralId): void
    {
        $ownTx = !$db->inTransaction();
        if ($ownTx) {
            $db->beginTransaction();
        }
        try {
            Dw::history($db, 'affiliate_referral', $referralId, 'UPDATE');
            $db->prepare(
                'UPDATE affiliate_referral SET last_seen = NOW(), updated = NOW() WHERE id = ?'
            )->execute([$referralId]);
            if ($ownTx) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($ownTx && $db->inTransaction()) {
                $db->rollBack();
            }
            // A failed last_seen touch must not break the page.
        }
    }

    private static function setRefCookie(string $visitorToken, string $code, string $referralId): void
    {
        $secure = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
            || (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https');
        $value = 'v1.' . $visitorToken . '.' . $code . '.' . $referralId;
        if (!headers_sent()) {
        setcookie(self::REF_COOKIE, $value, [
            'expires' => time() + (self::REF_WINDOW_DAYS * 86400),
            'path' => '/',
            'secure' => $secure,
            'httponly' => false,
            'samesite' => 'Lax',
        ]);
        }
        $_COOKIE[self::REF_COOKIE] = $value;
    }

    private static function ipHash(string $ip): string
    {
        $salt = '';
        if (is_readable(self::REF_SALT_FILE)) {
            $salt = trim((string)file_get_contents(self::REF_SALT_FILE));
        }
        if ($salt === '' && is_dir(dirname(self::REF_SALT_FILE))) {
            $generated = bin2hex(random_bytes(32));
            if (@file_put_contents(self::REF_SALT_FILE, $generated, LOCK_EX) !== false) {
                @chmod(self::REF_SALT_FILE, 0600);
                $salt = $generated;
            }
        }
        if ($salt === '') {
            $salt = 'dw-affiliate-referral-uninitialized';
        }
        return hash('sha256', $salt . "\0" . $ip);
    }

    private static function requestIp(): string
    {
        $ip = trim((string)($_SERVER['REMOTE_ADDR'] ?? ''));
        if ($ip === '' || filter_var($ip, FILTER_VALIDATE_IP) === false) {
            return '0.0.0.0';
        }
        return $ip;
    }

    private static function requestLandingUrl(): string
    {
        $host = strtolower((string)($_SERVER['HTTP_HOST'] ?? ''));
        $host = preg_replace('/:\d+$/', '', $host) ?? $host;
        if ($host === '' || !preg_match('/^[a-z0-9.-]+$/', $host)) {
            // Last-resort for CLI/tests with no Host. Public pages always send a host.
            $host = DwBrand::appHost();
        }
        $uri = (string)($_SERVER['REQUEST_URI'] ?? '/');
        $uri = str_replace(["\r", "\n"], '', $uri);
        if ($uri === '' || $uri[0] !== '/') {
            $uri = '/';
        }
        $url = $host . $uri;
        if (strlen($url) > 1024) {
            $url = substr($url, 0, 1024);
        }
        return $url;
    }

    private static function requestReferrer(): ?string
    {
        $ref = trim((string)($_SERVER['HTTP_REFERER'] ?? ''));
        if ($ref === '') {
            return null;
        }
        $ref = str_replace(["\r", "\n"], '', $ref);
        if (strlen($ref) > 1024) {
            $ref = substr($ref, 0, 1024);
        }
        return $ref;
    }

    private static function requestUserAgent(): ?string
    {
        $ua = trim((string)($_SERVER['HTTP_USER_AGENT'] ?? ''));
        if ($ua === '') {
            return null;
        }
        $ua = str_replace(["\r", "\n"], '', $ua);
        if (strlen($ua) > 512) {
            $ua = substr($ua, 0, 512);
        }
        return $ua;
    }

    private static function utmField(string $name): ?string
    {
        $value = trim((string)($_GET[$name] ?? $_POST[$name] ?? ''));
        if ($value === '') {
            return null;
        }
        $value = str_replace(["\r", "\n"], '', $value);
        if (strlen($value) > 100) {
            $value = substr($value, 0, 100);
        }
        return $value;
    }

    private static function optionalId(mixed $id): ?string
    {
        if (!is_string($id)) {
            return null;
        }
        $id = trim($id);
        if ($id === '' || !preg_match('/^[a-f0-9]{50}$/i', $id)) {
            return null;
        }
        return $id;
    }


    // ------------------------------------------------------------------ referred-client discount (refs #64)
    // A client who subscribes after arriving through an affiliate's link or code pays DISCOUNT_PERCENT less for the
    // first DISCOUNT_MONTHS months, then the regular price. The discount lives in PayPal, on a parallel "referred"
    // plan per regular plan (a TRIAL cycle at the discounted price, then the REGULAR cycle), listed under "referred"
    // in plans-live.json / plans-sandbox.json. Only subscriptions are discounted (never one-off store orders), and
    // never the affiliate add-on itself. The affiliate earns COMMISSION_RATE of what the client actually paid.
    public const DISCOUNT_PERCENT = 20;
    public const DISCOUNT_MONTHS = 12;
    public const DISCOUNT_SOURCE = 'affiliate';
    /** Historic default fraction (20%). New work uses the referral snapshot; this remains the fallback. */
    public const COMMISSION_RATE = '0.2000';
    public const DISCOUNT_CONFIG_FILE = '/var/lib/app/data/affiliate-discount.json';
    public const DISCOUNT_BANNER = 'Referred by an affiliate: 20% off your first year';

    /** Kill switch: {"enabled": false} in affiliate-discount.json turns new discounted subscriptions off. */
    public static function discountEnabled(): bool
    {
        $raw = @file_get_contents(self::DISCOUNT_CONFIG_FILE);
        $j = is_string($raw) ? json_decode($raw, true) : null;
        return !(is_array($j) && array_key_exists('enabled', $j) && $j['enabled'] === false);
    }

    private static function centsOf(string $dec): int
    {
        return (int)round(((float)$dec) * 100);
    }

    public static function moneyOf(int $cents): string
    {
        return number_format($cents / 100, 2, '.', '');
    }

    /** Discounted price in cents (half up). 1000 cents at 20% -> 800. */
    public static function discountedCents(int $regularCents, int $percent = self::DISCOUNT_PERCENT): int
    {
        return intdiv($regularCents * (100 - $percent) + 50, 100);
    }

    /** Billing cycles the discount lasts: 12 for monthly, 1 for yearly; null when the interval does not divide the term. */
    public static function discountCycles(string $interval, int $count, int $months = self::DISCOUNT_MONTHS): ?int
    {
        $count = max(1, $count);
        $per = $interval === 'MONTH' ? $count : ($interval === 'YEAR' ? 12 * $count : 0);
        if ($per < 1 || $per > $months || $months % $per !== 0) {
            return null;
        }
        return intdiv($months, $per);
    }

    /**
     * The referred plan for a regular plan, from plans-live.json (env live) or plans-sandbox.json (env sandbox).
     * Every recorded term must match what we would compute now (price, percent, cycles, interval), so a plan that
     * went stale after a price change is never used and the client simply gets the regular plan.
     *
     * @return array{plan_id:string,cycles:int,percent:int,months:int,regular_cents:int,discounted_cents:int}|null
     */
    public static function referredPlan(string $regularPlanId, string $variantPrice, string $interval, int $count, ?string $env = null, ?string $dir = null, ?int $percent = null, ?int $months = null): ?array
    {
        $percent = $percent ?? self::DISCOUNT_PERCENT;
        $months = $months ?? self::DISCOUNT_MONTHS;
        if ($percent < 0 || $percent > 100 || $months < 0 || $months > 120) {
            return null;
        }
        if (!preg_match('/^P-[A-Z0-9]+$/', $regularPlanId)) {
            return null;
        }
        if ($env === null || $dir === null) {
            $p = [];
            try {
                $p = (array)(DwStore::storeCfg()['paypal'] ?? []);
            } catch (Throwable $e) {
            }
            $env = $env ?? (($p['env'] ?? 'sandbox') === 'live' ? 'live' : 'sandbox');
            $dir = $dir ?? (string)($p['credentials_dir'] ?? '/var/lib/app/data/paypal');
        }
        $raw = @file_get_contents($dir . '/plans-' . ($env === 'live' ? 'live' : 'sandbox') . '.json');
        $j = is_string($raw) ? json_decode($raw, true) : null;
        $ref = is_array($j) ? ($j['referred'] ?? null) : null;
        if (!is_array($ref)) {
            return null;
        }
        $cycles = self::discountCycles($interval, $count, $months);
        $regular = self::centsOf($variantPrice);
        if ($cycles === null || $regular <= 0) {
            return null;
        }
        $want = self::discountedCents($regular, $percent);
        foreach ($ref as $e) {
            if (!is_array($e) || ($e['regular_plan'] ?? '') !== $regularPlanId) {
                continue;
            }
            $id = (string)($e['id'] ?? '');
            $ok = preg_match('/^P-[A-Z0-9]+$/', $id) === 1
                && (int)($e['percent'] ?? 0) === $percent
                && (int)($e['months'] ?? 0) === $months
                && (int)($e['cycles'] ?? 0) === $cycles
                && (string)($e['interval'] ?? '') === $interval
                && (int)($e['interval_count'] ?? 1) === max(1, $count)
                && self::centsOf((string)($e['regular_price'] ?? '0')) === $regular
                && self::centsOf((string)($e['price'] ?? '0')) === $want;
            if ($ok) {
                return ['plan_id' => $id, 'cycles' => $cycles, 'percent' => $percent, 'months' => $months,
                    'regular_cents' => $regular, 'discounted_cents' => $want];
            }
        }
        return null;
    }

    /**
     * Who referred this visitor, if anyone: the first-touch dw_ref cookie, else an explicit ref/aff code on this
     * request (which also records the touch and sets the cookie). The affiliate must be active and the referral
     * inside the 90-day window. A client is never referred by themselves (same person or a shared email).
     *
     * @return array{affiliate_id:string,affiliate_channel_id:?string,referral_id:string,code:string}|null
     */
    public static function attributionFromRequest(PDO $db, ?string $customerPersonId = null, ?array $jsonBody = null): ?array
    {
        try {
            $got = self::captureReferralFromRequest($db, 'url_param', $jsonBody);
            if ($got === null) {
                return null;
            }
            $brand = self::requestBrand($db);
            if ($brand === null) {
                return null;
            }
            $q = $db->prepare(
                "SELECT r.id AS referral_id, r.affiliate_id, r.affiliate_channel_id, r.code
                   FROM affiliate_referral r
                   JOIN affiliate a ON a.affiliate_id = r.affiliate_id
                   JOIN person p ON p.id = a.person_id
                  WHERE r.id = ? AND a.status = 'active' AND p.brand = ?
                    AND r.first_seen >= DATE_SUB(NOW(), INTERVAL ? DAY)"
            );
            $q->execute([$got['referral_id'], $brand, self::REF_WINDOW_DAYS]);
            $r = $q->fetch(PDO::FETCH_ASSOC);
            if (!is_array($r)) {
                return null;
            }
            if ($customerPersonId !== null && self::isSelfReferral($db, (string)$r['affiliate_id'], $customerPersonId)) {
                return null;
            }
            return [
                'affiliate_id' => (string)$r['affiliate_id'],
                'affiliate_channel_id' => $r['affiliate_channel_id'] !== null ? (string)$r['affiliate_channel_id'] : null,
                'referral_id' => (string)$r['referral_id'],
                'code' => (string)$r['code'],
            ];
        } catch (Throwable $e) {
            return null;
        }
    }

    public static function isSelfReferral(PDO $db, string $affiliateId, string $personId): bool
    {
        $q = $db->prepare('SELECT person_id FROM affiliate WHERE affiliate_id = ?');
        $q->execute([$affiliateId]);
        $affPerson = $q->fetchColumn();
        if (!is_string($affPerson) || $affPerson === '') {
            return false;
        }
        if ($affPerson === $personId) {
            return true;
        }
        $q = $db->prepare(
            "SELECT 1 FROM email a JOIN email c ON LOWER(TRIM(c.email)) = LOWER(TRIM(a.email))
              WHERE a.owner_id = ? AND a.owner_type = 'PRSN' AND c.owner_id = ? AND c.owner_type = 'PRSN' LIMIT 1"
        );
        $q->execute([$affPerson, $personId]);
        return $q->fetchColumn() !== false;
    }

    /**
     * Decide the plan for a subscribe or quote request.
     * $ctx: person_id, entitlement (the product's first entitlement), plan_id (regular PayPal plan), price
     * (variant price, e.g. "10.00"), interval (MONTH|YEAR), interval_count, json (optional request body).
     *
     * @return array{attribution:?array,discount:?array}  discount = referredPlan() result when this client gets it
     */
    public static function planSubscription(PDO $db, array $ctx): array
    {
        $none = ['attribution' => null, 'discount' => null];
        if (($ctx['entitlement'] ?? '') === self::GATE_FEATURE) {
            return $none;   // the affiliate add-on itself is never discounted and earns no commission
        }
        $attr = self::attributionFromRequest($db, (string)($ctx['person_id'] ?? '') ?: null, $ctx['json'] ?? null);
        if ($attr === null) {
            return $none;
        }
        $disc = null;
        $brand = self::requestBrand($db);
        $settings = $brand !== null ? self::programSettings($db, $brand) : null;
        if ($settings !== null && $settings['program_enabled'] && self::discountEnabled()) {
            $disc = self::referredPlan(
                (string)$ctx['plan_id'],
                (string)$ctx['price'],
                (string)$ctx['interval'],
                (int)($ctx['interval_count'] ?? 1),
                null,
                null,
                (int)round((float)$settings['client_discount_percent']),
                (int)$settings['client_discount_months']
            );
        }
        return ['attribution' => $attr, 'discount' => $disc];
    }

    /** Text for the subscribe page and quote. */
    public static function discountText(array $discount, int $thenCents, string $interval): string
    {
        return 'Referred by an affiliate: ' . $discount['percent'] . '% off for the first ' . $discount['months'] . ' months, then $'
            . self::moneyOf($thenCents) . ' / ' . ($interval === 'YEAR' ? 'year' : 'month');
    }

    /**
     * Record the attribution and the discount terms for a new subscription invoice (inside the caller's
     * transaction). $row: invoice_id, person_id, variant_id, regular_unit, discounted_unit, regular_tax,
     * discounted_tax (cents), discount (the referredPlan result or null).
     */
    public static function recordSubscription(PDO $db, array $attribution, array $row): string
    {
        $id = Dw::randId();
        $d = $row['discount'] ?? null;
        $percent = self::DEFAULT_COMMISSION_PERCENT;
        if (!empty($attribution['referral_id'])) {
            $pq = $db->prepare('SELECT commission_percent FROM affiliate_referral WHERE id = ?');
            $pq->execute([$attribution['referral_id']]);
            $pv = $pq->fetchColumn();
            if (is_string($pv) && self::parsePercent($pv) !== null) {
                $percent = self::parsePercent($pv);
            }
        }
        $db->prepare(
            'INSERT INTO affiliate_subscription
               (id, invoice_id, paypal_subscription_id, affiliate_id, affiliate_channel_id, referral_id, person_id, variant_id,
                discount_source, discount_percent, discount_months, commission_percent, regular_unit, discounted_unit, regular_tax, discounted_tax,
                referred_plan_id, starts_at, ends_at, created, updated)
             VALUES (?, ?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, NOW(), NOW())'
        )->execute([
            $id, $row['invoice_id'], $attribution['affiliate_id'], $attribution['affiliate_channel_id'], $attribution['referral_id'],
            $row['person_id'], $row['variant_id'], self::DISCOUNT_SOURCE,
            $d ? self::moneyOf($d['percent'] * 100) : '0.00', $d ? $d['months'] : 0, $percent,
            self::moneyOf((int)$row['regular_unit']), self::moneyOf((int)$row['discounted_unit']),
            self::moneyOf((int)$row['regular_tax']), self::moneyOf((int)$row['discounted_tax']),
            $d ? $d['plan_id'] : null,
        ]);
        Dw::history($db, 'affiliate_subscription', $id, 'INSERT');
        return $id;
    }

    public static function linkPayPalSubscription(PDO $db, string $invoiceId, string $paypalSubscriptionId): void
    {
        $q = $db->prepare('SELECT id FROM affiliate_subscription WHERE invoice_id = ?');
        $q->execute([$invoiceId]);
        $id = $q->fetchColumn();
        if (!is_string($id)) {
            return;
        }
        Dw::history($db, 'affiliate_subscription', $id, 'UPDATE');
        $db->prepare('UPDATE affiliate_subscription SET paypal_subscription_id = ?, updated = NOW() WHERE id = ?')
            ->execute([substr($paypalSubscriptionId, 0, 64), $id]);
    }

    /**
     * Net paid (cents, no sales tax) for a payment of $paidCents on this subscription: the first-period price when the
     * payment matches the discounted charge, the regular price when it matches that, else the payment with the
     * regular tax share taken out.
     *
     * @param array{regular_unit:int,discounted_unit:int,regular_tax:int,discounted_tax:int} $s cents
     */
    public static function netPaidCents(int $paidCents, array $s): int
    {
        if ($paidCents === $s['discounted_unit'] + $s['discounted_tax']) {
            return $s['discounted_unit'];
        }
        if ($paidCents === $s['regular_unit'] + $s['regular_tax']) {
            return $s['regular_unit'];
        }
        $den = $s['regular_unit'] + $s['regular_tax'];
        return $den > 0 ? intdiv($paidCents * $s['regular_unit'] * 2 + $den, $den * 2) : $paidCents;
    }

    public static function commissionCents(int $netPaidCents, string $rate = self::COMMISSION_RATE): int
    {
        $bp = (int)round(((float)$rate) * 10000);
        return intdiv($netPaidCents * $bp + 5000, 10000);
    }

    /**
     * An invoice of an attributed subscription is fully paid: write (or refresh) its commission row at the
     * attribution snapshot rate of the net paid, record the current owner, start the discount clock on the
     * first invoice, and credit the referral. A 0% snapshot still writes a $0.00 row. Idempotent per invoice.
     * Rows already approved or paid are left alone. Returns the ledger row.
     */
    public static function onInvoicePaid(PDO $db, string $invoiceId): ?array
    {
        $q = $db->prepare('SELECT id, total, paypal_subscription_id FROM invoice WHERE id = ?');
        $q->execute([$invoiceId]);
        $inv = $q->fetch(PDO::FETCH_ASSOC);
        if (!is_array($inv)) {
            return null;
        }
        $q = $db->prepare('SELECT * FROM affiliate_subscription WHERE invoice_id = ?');
        $q->execute([$invoiceId]);
        $sub = $q->fetch(PDO::FETCH_ASSOC);
        if (!is_array($sub) && ($inv['paypal_subscription_id'] ?? '') !== '') {
            $q = $db->prepare('SELECT * FROM affiliate_subscription WHERE paypal_subscription_id = ? ORDER BY created LIMIT 1');
            $q->execute([$inv['paypal_subscription_id']]);
            $sub = $q->fetch(PDO::FETCH_ASSOC);
        }
        if (!is_array($sub)) {
            return null;
        }
        $q = $db->prepare("SELECT COALESCE(SUM(amount), 0) FROM payments WHERE invoice_id = ? AND status = 'COMPLETED'");
        $q->execute([$invoiceId]);
        $paid = self::centsOf((string)$q->fetchColumn());
        if ($paid <= 0 || $paid < self::centsOf((string)$inv['total'])) {
            return null;
        }
        $q = $db->prepare("SELECT status FROM affiliate WHERE affiliate_id = ?");
        $q->execute([$sub['affiliate_id']]);
        if ($q->fetchColumn() !== 'active') {
            return null;
        }
        $cents = [
            'regular_unit' => self::centsOf((string)$sub['regular_unit']),
            'discounted_unit' => self::centsOf((string)$sub['discounted_unit']),
            'regular_tax' => self::centsOf((string)$sub['regular_tax']),
            'discounted_tax' => self::centsOf((string)$sub['discounted_tax']),
        ];
        $net = self::netPaidCents($paid, $cents);
        $gross = $cents['regular_unit'];
        $discount = max(0, $gross - $net);
        $percent = self::parsePercent($sub['commission_percent'] ?? '') ?? self::DEFAULT_COMMISSION_PERCENT;
        if ($percent === self::DEFAULT_COMMISSION_PERCENT && !empty($sub['referral_id'])) {
            $pq = $db->prepare('SELECT commission_percent FROM affiliate_referral WHERE id = ?');
            $pq->execute([$sub['referral_id']]);
            $pv = self::parsePercent($pq->fetchColumn() ?: '');
            if ($pv !== null) {
                $percent = $pv;
            }
        }
        $rate = self::percentToRate($percent);
        // 0% still writes a $0.00 ledger row (zero-rate policy, refs #69).
        $commission = self::commissionCents($net, $rate);
        $q = $db->prepare("SELECT id FROM payments WHERE invoice_id = ? AND status = 'COMPLETED' ORDER BY created, id LIMIT 1");
        $q->execute([$invoiceId]);
        $payId = $q->fetchColumn();
        $payId = is_string($payId) ? $payId : null;

        $oq = $db->prepare('SELECT owner_person_id, owner_company_id FROM affiliate WHERE affiliate_id = ?');
        $oq->execute([$sub['affiliate_id']]);
        $owner = $oq->fetch(PDO::FETCH_ASSOC) ?: [];
        $ownerPerson = (string)($owner['owner_person_id'] ?? '');
        $ownerCompany = $owner['owner_company_id'] ?? null;
        $ownerCompany = is_string($ownerCompany) && $ownerCompany !== '' ? $ownerCompany : null;

        $q = $db->prepare('SELECT * FROM affiliate_commission WHERE invoice_id = ? FOR UPDATE');
        $q->execute([$invoiceId]);
        $have = $q->fetch(PDO::FETCH_ASSOC);
        if (is_array($have)) {
            if (in_array($have['status'], ['approved', 'paid'], true)) {
                return $have;
            }
            Dw::history($db, 'affiliate_commission', (string)$have['id'], 'UPDATE');
            // Amounts and rate may refresh on a pending/reversed row; the owner written at creation stays put.
            $db->prepare(
                "UPDATE affiliate_commission SET payment_id = ?, gross = ?, discount = ?, net_paid = ?, rate = ?, commission = ?,
                        status = 'pending', reversed_at = NULL, updated = NOW() WHERE id = ?"
            )->execute([$payId, self::moneyOf($gross), self::moneyOf($discount), self::moneyOf($net), $rate, self::moneyOf($commission), $have['id']]);
            $id = (string)$have['id'];
        } else {
            $id = Dw::randId();
            $db->prepare(
                "INSERT INTO affiliate_commission
                   (id, affiliate_id, owner_person_id, owner_company_id, affiliate_channel_id, affiliate_subscription_id, invoice_id, payment_id, paypal_subscription_id,
                    gross, discount, net_paid, rate, commission, status, reversed_at, created, updated)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', NULL, NOW(), NOW())"
            )->execute([$id, $sub['affiliate_id'], $ownerPerson !== '' ? $ownerPerson : null, $ownerCompany, $sub['affiliate_channel_id'], $sub['id'], $invoiceId, $payId,
                $inv['paypal_subscription_id'] ?: $sub['paypal_subscription_id'],
                self::moneyOf($gross), self::moneyOf($discount), self::moneyOf($net), $rate, self::moneyOf($commission)]);
            Dw::history($db, 'affiliate_commission', $id, 'INSERT');
        }
        // The discount clock starts when the first invoice is paid.
        if ($sub['invoice_id'] === $invoiceId && $sub['starts_at'] === null) {
            Dw::history($db, 'affiliate_subscription', (string)$sub['id'], 'UPDATE');
            $months = (int)$sub['discount_months'];
            $db->prepare(
                'UPDATE affiliate_subscription SET starts_at = NOW(), ends_at = ' . ($months > 0 ? 'DATE_ADD(NOW(), INTERVAL ' . $months . ' MONTH)' : 'NULL') . ', updated = NOW() WHERE id = ?'
            )->execute([$sub['id']]);
        }
        self::creditReferral($db, (string)$sub['referral_id'], (string)$sub['person_id'], $invoiceId);
        $q = $db->prepare('SELECT * FROM affiliate_commission WHERE id = ?');
        $q->execute([$id]);
        return $q->fetch(PDO::FETCH_ASSOC) ?: null;
    }

    /** Mark the referral converted (once) from a webhook-time payment, where the visitor's cookie is not available. */
    private static function creditReferral(PDO $db, string $referralId, string $personId, string $invoiceId): void
    {
        $q = $db->prepare('SELECT converted_at FROM affiliate_referral WHERE id = ? FOR UPDATE');
        $q->execute([$referralId]);
        $row = $q->fetch(PDO::FETCH_ASSOC);
        if (!is_array($row) || $row['converted_at'] !== null) {
            return;
        }
        Dw::history($db, 'affiliate_referral', $referralId, 'UPDATE');
        $db->prepare(
            "UPDATE affiliate_referral SET converted_person_id = ?, converted_reference_type = 'subscription', converted_reference_id = ?,
                    converted_at = NOW(), last_seen = NOW(), updated = NOW() WHERE id = ? AND converted_at IS NULL"
        )->execute([$personId, $invoiceId, $referralId]);
    }

    /** A refund, void or reversal on the invoice: its commission is reversed (unless already approved or paid out). */
    public static function reverseCommission(PDO $db, string $invoiceId): int
    {
        $q = $db->prepare("SELECT id FROM affiliate_commission WHERE invoice_id = ? AND status = 'pending' FOR UPDATE");
        $q->execute([$invoiceId]);
        $n = 0;
        foreach ($q->fetchAll(PDO::FETCH_COLUMN) as $id) {
            Dw::history($db, 'affiliate_commission', (string)$id, 'UPDATE');
            $db->prepare("UPDATE affiliate_commission SET status = 'reversed', reversed_at = NOW(), updated = NOW() WHERE id = ?")->execute([$id]);
            $n++;
        }
        return $n;
    }


    /**
     * Parse a commission percent. Accepts 0–100 inclusive (int, float, or string, optional trailing %).
     * At most two decimal places. Returns a normalized '0.00'..'100.00' string, or null if invalid.
     * Null is "invalid", not "clear the override" — callers treat a missing/empty input separately.
     */
    public static function parsePercent(mixed $value): ?string
    {
        if (is_int($value) || is_float($value)) {
            $s = (string)$value;
        } elseif (is_string($value)) {
            $s = trim($value);
            if (str_ends_with($s, '%')) {
                $s = trim(substr($s, 0, -1));
            }
        } else {
            return null;
        }
        if ($s === '' || preg_match('/^-?\d+(\.\d+)?$/', $s) !== 1) {
            return null;
        }
        if (preg_match('/^-?\d+\.(\d+)$/', $s, $m) === 1 && strlen($m[1]) > 2) {
            return null;
        }
        $cents = (int)round(((float)$s) * 100);
        if (abs(((float)$s) * 100 - $cents) > 0.0001) {
            return null;
        }
        if ($cents < 0 || $cents > 10000) {
            return null;
        }
        return number_format($cents / 100, 2, '.', '');
    }

    /** Convert a percent ('20.00') to the ledger fraction ('0.2000'). */
    public static function percentToRate(string $percent): string
    {
        $parsed = self::parsePercent($percent);
        if ($parsed === null) {
            throw new InvalidArgumentException('DwAffiliate::percentToRate: percent must be 0–100');
        }
        $cents = (int)round(((float)$parsed) * 100);
        return number_format($cents / 10000, 4, '.', '');
    }

    public static function defaultCommissionPercent(PDO $db, string $brand): string
    {
        $q = $db->prepare('SELECT default_commission_percent FROM affiliate_brand_setting WHERE brand = ?');
        $q->execute([$brand]);
        $v = self::parsePercent($q->fetchColumn() ?: '');
        return $v ?? self::DEFAULT_COMMISSION_PERCENT;
    }

    /**
     * Staff: set the brand default percent for new referrals (0–100). Creates the setting row if needed.
     * @return array{ok:bool,error?:string,percent?:string}
     */
    public static function setDefaultCommissionPercent(PDO $db, string $brand, mixed $percent, string $byPersonId): array
    {
        $parsed = self::parsePercent($percent);
        if ($parsed === null) {
            return ['ok' => false, 'error' => 'commission rate must be a number from 0 to 100'];
        }
        if (preg_match('/^[A-Za-z0-9]{1,10}$/', $brand) !== 1) {
            return ['ok' => false, 'error' => 'brand is not valid'];
        }
        $own = !$db->inTransaction();
        if ($own) {
            $db->beginTransaction();
        }
        try {
            $q = $db->prepare('SELECT id FROM affiliate_brand_setting WHERE brand = ? FOR UPDATE');
            $q->execute([$brand]);
            $id = $q->fetchColumn();
            if (is_string($id) && $id !== '') {
                Dw::history($db, 'affiliate_brand_setting', $id, 'UPDATE');
                $db->prepare('UPDATE affiliate_brand_setting SET default_commission_percent = ?, last_updated = NOW(), last_updated_by = ? WHERE id = ?')
                    ->execute([$parsed, $byPersonId, $id]);
            } else {
                $id = Dw::randId();
                $db->prepare(
                    'INSERT INTO affiliate_brand_setting (id, brand, default_commission_percent, created, created_by, last_updated, last_updated_by)
                     VALUES (?, ?, ?, NOW(), ?, NOW(), ?)'
                )->execute([$id, $brand, $parsed, $byPersonId, $byPersonId]);
                Dw::history($db, 'affiliate_brand_setting', $id, 'INSERT');
            }
            if ($own) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($own && $db->inTransaction()) {
                $db->rollBack();
            }
            error_log('affiliate setDefaultCommissionPercent: ' . $e->getMessage());
            return ['ok' => false, 'error' => 'could not save the default commission rate'];
        }
        return ['ok' => true, 'percent' => $parsed];
    }


    /** Pin requestBrand() for the rest of this request (OAuth Bearer: the token's brand, checked against Host first). */
    public static function pinRequestBrand(?string $brand): void
    {
        self::$requestBrandOverride = $brand;
    }

    /** Test-only: pin requestBrand() so unit tests do not depend on Host / DwDomain cache. Pass null to clear. */
    public static function setRequestBrandForTest(?string $brand): void
    {
        self::$requestBrandOverride = $brand;
    }

    /**
     * Brand for this HTTP request: the domain table row for the Host header (www. and bare host both tried).
     * No fallback to the original platform brand. App hosts and unknown hosts return null.
     */
    public static function requestBrand(PDO $db, ?string $host = null): ?string
    {
        if (self::$requestBrandOverride !== null && self::$requestBrandOverride !== '') {
            return self::$requestBrandOverride;
        }
        $lib = '/var/www/html/lib/DwDomain.php';
        if (is_file($lib)) {
            require_once $lib;
        } elseif (is_file(__DIR__ . '/DwDomain.php')) {
            require_once __DIR__ . '/DwDomain.php';
        }
        if ($host === null) {
            if (class_exists('DwDomain', false)) {
                $host = DwDomain::requestHost();
            } else {
                $host = strtolower((string)($_SERVER['HTTP_HOST'] ?? ''));
                $host = preg_replace('/:\d+$/', '', $host) ?? $host;
            }
        }
        $host = strtolower(trim((string)$host));
        $host = preg_replace('/:\d+$/', '', $host) ?? $host;
        if ($host === '' || !preg_match('/^[a-z0-9.-]+$/', $host)) {
            return null;
        }
        if (!class_exists('DwDomain', false)) {
            return null;
        }
        $lookup = static function (string $h) use ($db): ?string {
            $brand = DwDomain::brandForHost($h, static fn () => $db);
            return is_string($brand) && $brand !== '' ? $brand : null;
        };
        $got = $lookup($host);
        if ($got !== null) {
            return $got;
        }
        $alt = str_starts_with($host, 'www.') ? substr($host, 4) : ('www.' . $host);
        return $lookup($alt);
    }

    /** Public hostname for a brand, if a domain is claimed. */
    public static function brandPublicHost(PDO $db, string $brand): ?string
    {
        if (preg_match('/^[A-Za-z0-9]{1,10}$/', $brand) !== 1) {
            return null;
        }
        $q = $db->prepare(
            "SELECT domain_name FROM domain WHERE code = ?
              ORDER BY domain_name LIKE 'www.%', domain_name LIKE 'app.%', domain_name
              LIMIT 1"
        );
        $q->execute([$brand]);
        $h = strtolower((string)($q->fetchColumn() ?: ''));
        $h = preg_replace('/:\d+$/', '', $h) ?? $h;
        return $h !== '' && preg_match('/^[a-z0-9.-]+$/', $h) === 1 ? $h : null;
    }

    /** Display name for program copy: the platform name (DwBrand) on platform hosts, else the brand's company or host. */
    public static function brandDisplayName(PDO $db, string $brand): string
    {
        $host = self::brandPublicHost($db, $brand) ?? '';
        if (DwBrand::isPlatformHost($host)) {
            return DwBrand::name();
        }
        $q = $db->prepare(
            "SELECT company_name FROM company
              WHERE brand = ? AND company_name IS NOT NULL AND TRIM(company_name) <> ''
              ORDER BY id LIMIT 1"
        );
        $q->execute([$brand]);
        $name = trim((string)($q->fetchColumn() ?: ''));
        if ($name !== '') {
            return $name;
        }
        return $host !== '' ? $host : 'The site owner';
    }

    /**
     * Per-brand program settings. A missing row means: enabled, 20% default commission, 20% off for 12 months, default terms.
     * @return array{program_enabled:bool,default_commission_percent:string,client_discount_percent:string,client_discount_months:int,terms:string,terms_custom:bool}
     */
    public static function programSettings(PDO $db, string $brand): array
    {
        $out = [
            'program_enabled' => true,
            'default_commission_percent' => self::DEFAULT_COMMISSION_PERCENT,
            'client_discount_percent' => number_format(self::DISCOUNT_PERCENT, 2, '.', ''),
            'client_discount_months' => self::DISCOUNT_MONTHS,
            'terms' => self::defaultTerms(),
            'terms_custom' => false,
        ];
        if (preg_match('/^[A-Za-z0-9]{1,10}$/', $brand) !== 1) {
            return $out;
        }
        $q = $db->prepare(
            'SELECT program_enabled, default_commission_percent, client_discount_percent, client_discount_months, terms
               FROM affiliate_brand_setting WHERE brand = ?'
        );
        $q->execute([$brand]);
        $row = $q->fetch(PDO::FETCH_ASSOC);
        if (is_array($row)) {
            $out['program_enabled'] = (int)$row['program_enabled'] === 1;
            $pct = self::parsePercent((string)($row['default_commission_percent'] ?? ''));
            if ($pct !== null) {
                $out['default_commission_percent'] = $pct;
            }
            $disc = self::parsePercent((string)($row['client_discount_percent'] ?? ''));
            if ($disc !== null) {
                $out['client_discount_percent'] = $disc;
            }
            $months = (int)$row['client_discount_months'];
            if ($months >= 0 && $months <= 120) {
                $out['client_discount_months'] = $months;
            }
            $custom = $row['terms'] !== null && trim((string)$row['terms']) !== '';
            $out['terms_custom'] = $custom;
            if ($custom) {
                $out['terms'] = (string)$row['terms'];
                return $out;
            }
        }
        $host = self::brandPublicHost($db, $brand);
        $out['terms'] = self::termsForSettings($out, self::brandDisplayName($db, $brand), $host !== null && DwBrand::isPlatformHost($host));
        return $out;
    }

    /**
     * Default join-page terms from settings + brand name. $platform adds the operator's legal clause
     * (AFFILIATE_TERMS_COMPANY / _SITE / _CONTACT / _JURISDICTION in DwConfig; each sentence only when set).
     */
    public static function termsForSettings(array $settings, string $displayName, bool $platform = false): string
    {
        $pct = rtrim(rtrim(number_format((float)($settings['client_discount_percent'] ?? self::DISCOUNT_PERCENT), 2, '.', ''), '0'), '.');
        if ($pct === '') {
            $pct = '0';
        }
        $months = (int)($settings['client_discount_months'] ?? self::DISCOUNT_MONTHS);
        $name = trim($displayName) !== '' ? trim($displayName) : 'The site owner';
        $duration = $months === 12 ? 'first year' : ('first ' . $months . ' months');
        $early = ($pct === '20' && $months === 12)
            ? " Referrals already recorded keep their existing rate, and early affiliates' existing referred clients stay at 20%."
            : ' Referrals already recorded keep their existing rate.';
        return 'Commission is a percentage of what the referred client actually pays for subscription services after any discount, not including tax or other fees. '
            . "Each client's commission rate is fixed for the life of that client's subscription, at the rate in effect when they were referred. "
            . "Clients you refer get {$pct}% off their {$duration}. "
            . "{$name} may change the commission rate for new referrals (higher or lower, including 0% or 100%); changes apply only to clients referred after the change."
            . $early
            . " Affiliate rights may be transferred or inherited when {$name} registers and approves the transfer. "
            . 'Commission on invoices paid after a transfer goes to the new owner; commission already recorded stays with the previous owner.'
            . ($platform ? self::legalClause() : '');
    }

    /** Operator legal clause for the platform's own terms; empty when AFFILIATE_TERMS_* are not set. */
    public static function legalClause(): string
    {
        $v = fn(string $k): string => trim((string)preg_replace('/[\x00-\x1F\x7F]+/', ' ', DwConfig::get('AFFILIATE_TERMS_' . $k)));
        $out = '';
        if ($v('COMPANY') !== '') {
            $out .= ' This program is run by ' . $v('COMPANY') . ($v('SITE') !== '' ? ' (' . $v('SITE') . ')' : '') . '.';
        } elseif ($v('SITE') !== '') {
            $out .= ' This program is run from ' . $v('SITE') . '.';
        }
        if ($v('CONTACT') !== '') {
            $out .= ' Questions about these terms: ' . $v('CONTACT') . '.';
        }
        if ($v('JURISDICTION') !== '') {
            $out .= ' These terms are governed by the laws of ' . $v('JURISDICTION') . '.';
        }
        return $out;
    }

    /**
     * Staff: save per-brand program settings (enabled, default commission, client discount, terms).
     * Pass terms as null or '' to use the generated default wording.
     * @param array{program_enabled?:mixed,default_commission_percent?:mixed,percent?:mixed,client_discount_percent?:mixed,client_discount_months?:mixed,terms?:mixed} $input
     * @return array{ok:bool,error?:string,settings?:array}
     */
    public static function setProgramSettings(PDO $db, string $brand, array $input, string $byPersonId): array
    {
        if (preg_match('/^[A-Za-z0-9]{1,10}$/', $brand) !== 1) {
            return ['ok' => false, 'error' => 'brand is not valid'];
        }
        $enabledRaw = $input['program_enabled'] ?? true;
        $enabled = in_array($enabledRaw, [1, '1', true, 'true', 'on', 'yes'], true) ? 1 : 0;
        if (in_array($enabledRaw, [0, '0', false, 'false', 'off', 'no', ''], true)) {
            $enabled = 0;
        }
        $default = self::parsePercent($input['default_commission_percent'] ?? $input['percent'] ?? null);
        if ($default === null) {
            return ['ok' => false, 'error' => 'commission rate must be a number from 0 to 100'];
        }
        $disc = self::parsePercent($input['client_discount_percent'] ?? self::DISCOUNT_PERCENT);
        if ($disc === null) {
            return ['ok' => false, 'error' => 'client discount must be a number from 0 to 100'];
        }
        if (!array_key_exists('client_discount_months', $input) || $input['client_discount_months'] === '' || $input['client_discount_months'] === null) {
            $months = self::DISCOUNT_MONTHS;
        } elseif (!is_numeric($input['client_discount_months'])) {
            return ['ok' => false, 'error' => 'client discount duration must be a number of months from 0 to 120'];
        } else {
            $months = (int)$input['client_discount_months'];
            if ($months < 0 || $months > 120) {
                return ['ok' => false, 'error' => 'client discount duration must be a number of months from 0 to 120'];
            }
        }
        $terms = $input['terms'] ?? null;
        if ($terms === null || (is_string($terms) && trim($terms) === '')) {
            $termsSql = null;
        } elseif (!is_string($terms)) {
            return ['ok' => false, 'error' => 'terms must be text'];
        } else {
            $terms = trim($terms);
            if (strlen($terms) > 20000) {
                return ['ok' => false, 'error' => 'terms are longer than 20000 characters'];
            }
            $termsSql = $terms;
        }
        $own = !$db->inTransaction();
        if ($own) {
            $db->beginTransaction();
        }
        try {
            $q = $db->prepare('SELECT id FROM affiliate_brand_setting WHERE brand = ? FOR UPDATE');
            $q->execute([$brand]);
            $id = $q->fetchColumn();
            if (is_string($id) && $id !== '') {
                Dw::history($db, 'affiliate_brand_setting', $id, 'UPDATE');
                $db->prepare(
                    'UPDATE affiliate_brand_setting
                        SET program_enabled = ?, default_commission_percent = ?, client_discount_percent = ?,
                            client_discount_months = ?, terms = ?, last_updated = NOW(), last_updated_by = ?
                      WHERE id = ?'
                )->execute([$enabled, $default, $disc, $months, $termsSql, $byPersonId, $id]);
            } else {
                $id = Dw::randId();
                $db->prepare(
                    'INSERT INTO affiliate_brand_setting
                        (id, brand, program_enabled, default_commission_percent, client_discount_percent,
                         client_discount_months, terms, created, created_by, last_updated, last_updated_by)
                     VALUES (?, ?, ?, ?, ?, ?, ?, NOW(), ?, NOW(), ?)'
                )->execute([$id, $brand, $enabled, $default, $disc, $months, $termsSql, $byPersonId, $byPersonId]);
                Dw::history($db, 'affiliate_brand_setting', $id, 'INSERT');
            }
            if ($own) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($own && $db->inTransaction()) {
                $db->rollBack();
            }
            error_log('affiliate setProgramSettings: ' . $e->getMessage());
            return ['ok' => false, 'error' => 'could not save the program settings'];
        }
        return ['ok' => true, 'settings' => self::programSettings($db, $brand)];
    }

    /**
     * Copy used to brand a verification email. When $brand is null the caller should pass no ctx so the
     * default DW Alliance wording (and envelope sender) stays unchanged for the email unit test.
     * @return array{join_url:?string,brand_name:string,brand_legal:string,site_url:string,site_label:string,terms_url:string,support_email:string,use_dw_chrome:bool,commission_percent:string,client_discount_percent:string,client_discount_months:int}
     */
    public static function emailContext(PDO $db, string $brand, ?string $joinUrl, ?array $settings = null): array
    {
        $settings = $settings ?? self::programSettings($db, $brand);
        $host = self::brandPublicHost($db, $brand);
        if ($host === null || $host === '') {
            $fromJoin = is_string($joinUrl) ? (parse_url($joinUrl, PHP_URL_HOST) ?: '') : '';
            $host = is_string($fromJoin) ? strtolower($fromJoin) : '';
        }
        $useDw = DwBrand::isPlatformHost($host) || $host === DwBrand::appHost();
        $name = $useDw ? DwBrand::name() : self::brandDisplayName($db, $brand);
        $siteUrl = $host !== '' ? ('https://' . $host) : 'https://' . DwBrand::domain();
        $label = $host !== '' ? $host : DwBrand::domain();
        $support = $useDw ? DwBrand::supportEmail() : ('support@' . ($host !== '' ? $host : DwBrand::domain()));
        return [
            'join_url' => $joinUrl,
            'brand_name' => $name,
            'brand_legal' => $useDw ? DwBrand::legalName() : $name,
            'site_url' => $siteUrl,
            'site_label' => $label,
            'terms_url' => $siteUrl . '/terms.html',
            'support_email' => $support,
            'use_dw_chrome' => $useDw,
            'commission_percent' => $settings['default_commission_percent'],
            'client_discount_percent' => $settings['client_discount_percent'],
            'client_discount_months' => (int)$settings['client_discount_months'],
        ];
    }

    public static function discountBannerText(array $settings): string
    {
        $pct = rtrim(rtrim(number_format((float)$settings['client_discount_percent'], 2, '.', ''), '0'), '.');
        if ($pct === '') {
            $pct = '0';
        }
        $months = (int)$settings['client_discount_months'];
        $duration = $months === 12 ? 'your first year' : ('your first ' . $months . ' months');
        return 'Referred by an affiliate: ' . $pct . '% off ' . $duration;
    }


    /**
     * Staff: set or clear the per-affiliate override used for NEW referrals. Pass null to clear (use brand default).
     * @return array{ok:bool,error?:string,percent?:?string}
     */
    public static function setCommissionOverride(PDO $db, string $affiliateId, mixed $percent, bool $clear, ?string $staffBrand = null): array
    {
        $parsed = null;
        if (!$clear) {
            $parsed = self::parsePercent($percent);
            if ($parsed === null) {
                return ['ok' => false, 'error' => 'commission rate must be a number from 0 to 100'];
            }
        }
        $own = !$db->inTransaction();
        if ($own) {
            $db->beginTransaction();
        }
        try {
            $q = $db->prepare(
                'SELECT a.affiliate_id, p.brand
                   FROM affiliate a JOIN person p ON p.id = a.person_id
                  WHERE a.affiliate_id = ? FOR UPDATE'
            );
            $q->execute([$affiliateId]);
            $row = $q->fetch(PDO::FETCH_ASSOC);
            if (!is_array($row)) {
                if ($own) {
                    $db->rollBack();
                }
                return ['ok' => false, 'error' => 'affiliate not found'];
            }
            if ($staffBrand !== null && $staffBrand !== '' && (string)$row['brand'] !== $staffBrand) {
                if ($own) {
                    $db->rollBack();
                }
                return ['ok' => false, 'error' => 'affiliate not found'];
            }
            self::history($db, 'affiliate', $affiliateId, 'UPDATE');
            $db->prepare('UPDATE affiliate SET commission_rate_override = ?, updated = NOW() WHERE affiliate_id = ?')
                ->execute([$parsed, $affiliateId]);
            if ($own) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($own && $db->inTransaction()) {
                $db->rollBack();
            }
            error_log('affiliate setCommissionOverride: ' . $e->getMessage());
            return ['ok' => false, 'error' => 'could not save the commission override'];
        }
        return ['ok' => true, 'percent' => $parsed];
    }

    /** Resolved percent for a NEW referral of this affiliate: override if set, otherwise the brand default. */
    public static function resolvedCommissionPercent(PDO $db, string $affiliateId): string
    {
        $q = $db->prepare('SELECT commission_rate_override, person_id FROM affiliate WHERE affiliate_id = ?');
        $q->execute([$affiliateId]);
        $row = $q->fetch(PDO::FETCH_ASSOC);
        if (!is_array($row)) {
            return self::DEFAULT_COMMISSION_PERCENT;
        }
        $over = self::parsePercent($row['commission_rate_override'] ?? '');
        if ($over !== null) {
            return $over;
        }
        return self::defaultCommissionPercent($db, self::brandForPerson($db, (string)$row['person_id']));
    }

    /**
     * Staff: register and approve a transfer of an affiliate right. Applied immediately.
     * Both parties are identified (current owner on the record, to-owner looked up by email on the brand).
     * @return array{ok:bool,error?:string,transfer?:array}
     */
    public static function transferOwnership(PDO $db, string $affiliateId, string $toEmail, string $reason, string $notes, string $staffPersonId, ?string $effectiveAt, ?string $toCompanyName = null, ?string $staffBrand = null, ?string $requestedBy = null): array
    {
        // requested_by: who asked (an approved API request keeps its requester); approved_by is always the staff person.
        $requestedBy = ($requestedBy !== null && $requestedBy !== '') ? $requestedBy : $staffPersonId;
        $toEmail = self::normalizeEmail($toEmail);
        if (!filter_var($toEmail, FILTER_VALIDATE_EMAIL)) {
            return ['ok' => false, 'error' => 'the new owner email is not valid'];
        }
        if (!isset(self::TRANSFER_REASONS[$reason])) {
            return ['ok' => false, 'error' => 'reason must be sale, inheritance, corporate_transfer, or other'];
        }
        $notes = trim($notes);
        if (strlen($notes) > 2000) {
            return ['ok' => false, 'error' => 'notes are longer than 2000 characters'];
        }
        $when = 'NOW()';
        $whenParam = null;
        if ($effectiveAt !== null && trim($effectiveAt) !== '') {
            $raw = trim($effectiveAt);
            $dt = date_create($raw);
            if ($dt === false) {
                return ['ok' => false, 'error' => 'effective date is not valid'];
            }
            $when = '?';
            $whenParam = $dt->format('Y-m-d H:i:s');
        }
        $own = !$db->inTransaction();
        if ($own) {
            $db->beginTransaction();
        }
        try {
            $q = $db->prepare(
                'SELECT affiliate_id, owner_person_id, owner_company_id, person_id FROM affiliate WHERE affiliate_id = ? FOR UPDATE'
            );
            $q->execute([$affiliateId]);
            $aff = $q->fetch(PDO::FETCH_ASSOC);
            if (!is_array($aff)) {
                if ($own) {
                    $db->rollBack();
                }
                return ['ok' => false, 'error' => 'affiliate not found'];
            }
            $brand = self::brandForPerson($db, (string)$aff['person_id']);
            if ($staffBrand !== null && $staffBrand !== '' && $brand !== $staffBrand) {
                if ($own) {
                    $db->rollBack();
                }
                return ['ok' => false, 'error' => 'affiliate not found'];
            }
            $toPerson = self::findPersonByEmail($db, $toEmail, $brand);
            if ($toPerson === null) {
                if ($own) {
                    $db->rollBack();
                }
                return ['ok' => false, 'error' => 'the new owner must already be a person on this brand (identified by email)'];
            }
            $toPersonId = $toPerson['id'];
            if ($toPersonId === (string)$aff['owner_person_id']) {
                if ($own) {
                    $db->rollBack();
                }
                return ['ok' => false, 'error' => 'the new owner is already the current owner'];
            }
            $toCompanyId = self::optionalCompanyForPerson($db, $toPersonId, $toCompanyName, $brand);
            $id = Dw::randId();
            $code = self::newCode($db, 'transfer');
            $cols = 'id, code, affiliate_id, from_owner_person_id, from_owner_company_id, to_owner_person_id, to_owner_company_id,
                     effective_at, reason, notes, requested_by, approved_by, approved_at, created, updated';
            if ($whenParam === null) {
                $db->prepare(
                    "INSERT INTO affiliate_ownership_transfer ($cols)
                     VALUES (?, ?, ?, ?, ?, ?, ?, NOW(), ?, ?, ?, ?, NOW(), NOW(), NOW())"
                )->execute([
                    $id, $code, $affiliateId, $aff['owner_person_id'], $aff['owner_company_id'],
                    $toPersonId, $toCompanyId, $reason, $notes !== '' ? $notes : null,
                    $requestedBy, $staffPersonId,
                ]);
            } else {
                $db->prepare(
                    "INSERT INTO affiliate_ownership_transfer ($cols)
                     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW(), NOW(), NOW())"
                )->execute([
                    $id, $code, $affiliateId, $aff['owner_person_id'], $aff['owner_company_id'],
                    $toPersonId, $toCompanyId, $whenParam, $reason, $notes !== '' ? $notes : null,
                    $requestedBy, $staffPersonId,
                ]);
            }
            Dw::history($db, 'affiliate_ownership_transfer', $id, 'INSERT');
            self::history($db, 'affiliate', $affiliateId, 'UPDATE');
            $db->prepare('UPDATE affiliate SET owner_person_id = ?, owner_company_id = ?, updated = NOW() WHERE affiliate_id = ?')
                ->execute([$toPersonId, $toCompanyId, $affiliateId]);
            if ($own) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($own && $db->inTransaction()) {
                $db->rollBack();
            }
            error_log('affiliate transferOwnership: ' . $e->getMessage());
            return ['ok' => false, 'error' => 'could not record the transfer'];
        }
        $q = $db->prepare('SELECT * FROM affiliate_ownership_transfer WHERE id = ?');
        $q->execute([$id]);
        $row = $q->fetch(PDO::FETCH_ASSOC) ?: ['id' => $id, 'code' => $code];
        return ['ok' => true, 'transfer' => $row];
    }

    /** @return array{id:string,first_name:string,last_name:string}|null */
    public static function personByEmail(PDO $db, string $email, string $brand): ?array
    {
        return self::findPersonByEmail($db, self::normalizeEmail($email), $brand);
    }

    /** @return array{id:string,first_name:string,last_name:string}|null */
    private static function findPersonByEmail(PDO $db, string $email, string $brand): ?array
    {
        $q = $db->prepare(
            "SELECT p.id, p.first_name, p.last_name
               FROM email e
               JOIN person p ON p.id = e.owner_id AND p.brand = e.brand
              WHERE e.email = ? AND e.owner_type = 'PRSN' AND e.brand = ?
              LIMIT 1"
        );
        $q->execute([$email, $brand]);
        $row = $q->fetch(PDO::FETCH_ASSOC);
        return is_array($row) ? $row : null;
    }

    private static function optionalCompanyForPerson(PDO $db, string $personId, ?string $companyName, string $brand): ?string
    {
        $name = trim((string)$companyName);
        if ($name !== '') {
            $q = $db->prepare('SELECT id FROM company WHERE company_name = ? AND brand = ? ORDER BY id LIMIT 1');
            $q->execute([$name, $brand]);
            $id = $q->fetchColumn();
            if (is_string($id) && $id !== '') {
                self::ensureRelation($db, $personId, $id, $brand);
                return $id;
            }
            return null;
        }
        $q = $db->prepare(
            "SELECT r.company FROM relation r
              JOIN company c ON c.id = r.company
             WHERE r.person_id = ? AND c.brand = ?
             ORDER BY r.created_on, r.company LIMIT 1"
        );
        $q->execute([$personId, $brand]);
        $id = $q->fetchColumn();
        return is_string($id) && $id !== '' ? $id : null;
    }

    /**
     * @return list<array<string,mixed>>
     */
    public static function listTransfers(PDO $db, string $affiliateId): array
    {
        $q = $db->prepare(
            'SELECT t.code, t.reason, t.notes, t.effective_at, t.approved_at, t.created,
                    t.from_owner_person_id, t.to_owner_person_id,
                    pf.first_name AS from_first, pf.last_name AS from_last,
                    pt.first_name AS to_first, pt.last_name AS to_last
               FROM affiliate_ownership_transfer t
               JOIN person pf ON pf.id = t.from_owner_person_id
               JOIN person pt ON pt.id = t.to_owner_person_id
              WHERE t.affiliate_id = ?
              ORDER BY t.effective_at DESC, t.created DESC'
        );
        $q->execute([$affiliateId]);
        return $q->fetchAll(PDO::FETCH_ASSOC) ?: [];
    }

    public const MODULE = 'AFFILIATE';
    public const MANAGE_RIGHTS = ['READ', 'CREATE', 'UPDATE', 'DELETE'];
    public const GATE_FEATURE = 'affiliate';
    public const GATE_CONFIG_FILE = '/var/lib/app/data/affiliate-gate.json';
    /** Flat monthly price per brand after the free allowance. Owner decision, 20 Nov 2026: $10/month. */
    public const GATE_PRICE = '10.00';
    /** @deprecated price is set; kept so older tests/comments still resolve */
    public const GATE_PRICE_PLACEHOLDER = self::GATE_PRICE;
    public const GATE_FREE_LIMIT = 10;
    public const GATE_SLUGS = ['affiliate-program', 'affiliate-program-test'];

    /**
     * Add-on gate, self-contained (no DwGate.php needed; reads affiliate-gate.json and brand_entitlement directly), plus the first-10-free allowance.
     *
     * Existing affiliates always keep working (allowed=true) even past 10 without
     * a subscription. A subscription is required only to approve or add the 11th
     * and later (can_add=false, with a subscribe prompt). The seller brand is
     * never billed. Subscriptions are not created automatically.
     *
     * @return array{
     *   feature:string,allowed:bool,can_add:bool,state:string,enforced:bool,
     *   grant_until:?string,grace_ends:?string,notice:?string,offer:?array,
     *   used:int,free_limit:int,subscribed:bool,pricing_summary:string,usage_summary:string
     * }
     */
    public static function gateCheck(PDO $db, string $brand): array
    {
        $cfg = self::gateConfig();
        $offer = self::gateOffer($db, $brand, $cfg);
        $used = self::countActiveAffiliates($db, $brand);
        $limit = $cfg['free_limit'];
        $price = (string)($offer['price'] ?? self::GATE_PRICE);
        $pricing = 'First ' . $limit . ' affiliates free; then $' . $price . '/month';
        $usage = $used . ' of ' . $limit . ' used';
        $out = [
            'feature' => self::GATE_FEATURE,
            'allowed' => true,
            'can_add' => true,
            'state' => 'allowance',
            'enforced' => false,
            'grant_until' => null,
            'grace_ends' => null,
            'notice' => $pricing . '. ' . $usage . '.',
            'offer' => $offer,
            'used' => $used,
            'free_limit' => $limit,
            'subscribed' => false,
            'pricing_summary' => $pricing,
            'usage_summary' => $usage,
        ];
        if (self::isSellerBrand($db, $brand)) {
            $out['state'] = 'seller';
            $out['subscribed'] = true;
            $out['notice'] = $pricing . '. The seller brand is not billed. ' . $usage . '.';
            return $out;
        }
        $grant = self::entitlementGrant($db, $brand);
        if (is_array($grant)) {
            $out['grant_until'] = $grant['grace_until'] ?? null;
            $out['state'] = 'subscribed';
            $out['subscribed'] = true;
            $out['notice'] = $pricing . '. This brand is subscribed. ' . $usage . '.';
            return $out;
        }
        if ($used < $limit) {
            $out['state'] = 'allowance';
            return $out;
        }
        // Past the free allowance, no subscription: do not lock existing affiliates.
        $out['can_add'] = false;
        $out['state'] = 'over_limit';
        $out['notice'] = $pricing . '. ' . $usage . '. Subscribe to add or approve more affiliates. Existing affiliates keep working.';
        $out['offer'] = $offer;
        return $out;
    }

    /**
     * @return array{enforce:bool,grace_days:int,grace_starts:?\DateTimeImmutable,price:string,label:string,currency:string,interval:string,subscribe_url:?string,free_limit:int,slugs:array}
     */
    public static function gateConfig(): array
    {
        $raw = [];
        $store = (string)@file_get_contents('/var/lib/app/data/store.json');
        $j = is_string($store) && $store !== '' ? json_decode($store, true) : null;
        if (is_array($j)) {
            $gates = (array)($j['entitlements']['gates'] ?? $j['gates'] ?? []);
            if (isset($gates['affiliate']) && is_array($gates['affiliate'])) {
                $raw = $gates['affiliate'];
            }
        }
        $file = @file_get_contents(self::GATE_CONFIG_FILE);
        if (is_string($file) && $file !== '') {
            $fj = json_decode($file, true);
            if (is_array($fj)) {
                $raw = array_merge($raw, $fj);
            }
        }
        $starts = null;
        if (is_string($raw['grace_starts'] ?? null) && $raw['grace_starts'] !== '') {
            try {
                $starts = new DateTimeImmutable((string)$raw['grace_starts']);
            } catch (Throwable $e) {
                $starts = null;
            }
        }
        $price = isset($raw['price']) && $raw['price'] !== '' && $raw['price'] !== null
            ? (string)$raw['price']
            : self::GATE_PRICE;
        $slugs = self::GATE_SLUGS;
        if (isset($raw['slugs']) && is_array($raw['slugs']) && $raw['slugs'] !== []) {
            $slugs = array_values(array_filter(array_map('strval', $raw['slugs'])));
        }
        $limit = isset($raw['free_limit']) ? (int)$raw['free_limit'] : self::GATE_FREE_LIMIT;
        if ($limit < 0) {
            $limit = 0;
        }
        return [
            'enforce' => ($raw['enforce'] ?? false) === true,
            'grace_days' => max(0, min(90, (int)($raw['grace_days'] ?? 0))),
            'grace_starts' => $starts,
            'price' => $price,
            'label' => (string)($raw['label'] ?? 'Affiliate program'),
            'currency' => (string)($raw['currency'] ?? 'USD'),
            'interval' => (string)($raw['interval'] ?? 'month'),
            'subscribe_url' => isset($raw['subscribe_url']) && is_string($raw['subscribe_url']) ? $raw['subscribe_url'] : null,
            'free_limit' => $limit,
            'slugs' => $slugs !== [] ? $slugs : self::GATE_SLUGS,
        ];
    }

    public static function gateOffer(PDO $db, string $brand, ?array $cfg = null): array
    {
        $cfg = $cfg ?? self::gateConfig();
        $site = null;
        try {
            $d = $db->prepare(DwBrand::t("SELECT domain_name FROM domain WHERE code = ? ORDER BY domain_name LIKE 'www.%', domain_name LIKE '%.dwalliance.com', domain_name LIMIT 1"));
            $d->execute([$brand]);
            $site = (string)($d->fetchColumn() ?: '');
            $site = strncmp($site, 'www.', 4) === 0 ? substr($site, 4) : $site;
            $site = $site !== '' ? $site : null;
        } catch (Throwable $e) {
            $site = null;
        }
        $sellerDomain = self::sellerDomain();
        $sellerBrand = '';
        $product = null;
        try {
            if (class_exists('DwDomain')) {
                $sellerBrand = (string)(DwDomain::brandForHost($sellerDomain, static fn () => $db) ?? '');
            }
            $slugs = $cfg['slugs'];
            if ($sellerBrand !== '' && $slugs !== []) {
                $in = implode(',', array_fill(0, count($slugs), '?'));
                $q = $db->prepare(
                    "SELECT p.slug, p.name, COALESCE(v.price, p.price) AS price, v.id AS variant_id, v.paypal_plan_id
                       FROM product p JOIN product_variant v ON v.product_id = p.id
                      WHERE p.brand = ? AND p.active = 1 AND p.slug IN ($in)
                        AND FIND_IN_SET(?, p.entitlements)
                        AND v.billing_interval = 'MONTH'
                      ORDER BY (v.paypal_plan_id LIKE 'P-%') DESC, FIELD(p.slug, $in), v.position
                      LIMIT 1"
                );
                $q->execute(array_merge([$sellerBrand], $slugs, [self::GATE_FEATURE], $slugs));
                $product = $q->fetch(PDO::FETCH_ASSOC) ?: null;
            }
        } catch (Throwable $e) {
            $product = null;
        }
        $slug = $product ? preg_replace('/-test$/', '', (string)$product['slug']) : 'affiliate-program';
        $url = $cfg['subscribe_url'] ?? ('https://' . $sellerDomain . '/store/subscribe/?plan=' . rawurlencode((string)$slug) . '&billing=monthly' . ($site ? ('&site=' . rawurlencode($site)) : ''));
        $price = $product['price'] ?? $cfg['price'];
        return [
            'feature' => self::GATE_FEATURE,
            'name' => $product['name'] ?? $cfg['label'],
            'price' => $price !== null ? (string)$price : self::GATE_PRICE,
            'interval' => $cfg['interval'],
            'currency' => $cfg['currency'],
            'site' => $site,
            'subscribe_url' => $url,
            'variant_id' => $product['variant_id'] ?? null,
            'has_paypal_plan' => is_string($product['paypal_plan_id'] ?? null) && str_starts_with((string)$product['paypal_plan_id'], 'P-'),
            'placeholder' => false,
            'pricing_summary' => 'First ' . $cfg['free_limit'] . ' affiliates free; then $' . ($price ?? self::GATE_PRICE) . '/month',
        ];
    }

    /**
     * Active affiliates for this brand: person.brand, company.brand, or
     * affiliate.company_id belonging to a company of the brand.
     */
    public static function countActiveAffiliates(PDO $db, string $brand): int
    {
        $q = $db->prepare(
            "SELECT COUNT(DISTINCT a.affiliate_id)
               FROM affiliate a
               JOIN person p ON p.id = a.person_id
               LEFT JOIN company c ON c.id = a.company_id
              WHERE a.status = 'active'
                AND (p.brand = ? OR c.brand = ? OR a.company_id IN (SELECT id FROM company WHERE brand = ?))"
        );
        $q->execute([$brand, $brand, $brand]);
        return (int)$q->fetchColumn();
    }

    /**
     * Whether this brand may approve or add another affiliate.
     * Logs and flags a refused 11th+ when there is no subscription. Does not
     * charge and does not create a subscription.
     *
     * @return array{can_add:bool,used:int,free_limit:int,subscribed:bool,state:string,notice:string,offer:?array,gate:array}
     */
    public static function canAddAffiliate(PDO $db, string $brand, bool $logIfRefused = false): array
    {
        $gate = self::gateCheck($db, $brand);
        $out = [
            'can_add' => !empty($gate['can_add']),
            'used' => (int)$gate['used'],
            'free_limit' => (int)$gate['free_limit'],
            'subscribed' => !empty($gate['subscribed']),
            'state' => (string)$gate['state'],
            'notice' => (string)($gate['notice'] ?? ''),
            'offer' => $gate['offer'] ?? null,
            'gate' => $gate,
        ];
        if ($logIfRefused && !$out['can_add']) {
            error_log(
                'affiliate over-limit: brand=' . $brand
                . ' used=' . $out['used']
                . ' free_limit=' . $out['free_limit']
                . ' no subscription; add/approve of a further affiliate refused. Existing affiliates kept working.'
            );
        }
        return $out;
    }

    /** Seller (platform) domain: store.json entitlements.seller_domain, default the platform domain (DwBrand). */
    public static function sellerDomain(): string
    {
        $j = json_decode((string)@file_get_contents('/var/lib/app/data/store.json'), true);
        $d = is_array($j) ? (string)(($j['entitlements']['seller_domain'] ?? '')) : '';
        $d = strtolower(trim($d));
        return $d !== '' && preg_match('/^[a-z0-9.-]+$/', $d) === 1 ? $d : DwBrand::domain();
    }

    public static function isSellerBrand(PDO $db, string $brand): bool
    {
        try {
            if (!class_exists('DwDomain')) {
                require_once '/var/www/html/lib/DwDomain.php';
            }
            $s = DwDomain::brandForHost(self::sellerDomain(), static fn () => $db);
            return $s !== null && $s !== '' && hash_equals((string)$s, $brand);
        } catch (Throwable $e) {
            return false;
        }
    }

    public static function entitlementGrant(PDO $db, string $brand): ?array
    {
        $q = $db->prepare(
            "SELECT id, status, paid_through, grace_until, provider_status FROM brand_entitlement
              WHERE brand = ? AND entitlement = ? AND status IN ('ACTIVE','CANCELLED')
                AND starts_at <= NOW() AND (grace_until IS NULL OR grace_until > NOW())
              ORDER BY grace_until IS NULL DESC, grace_until DESC
              LIMIT 1"
        );
        $q->execute([$brand, self::GATE_FEATURE]);
        $r = $q->fetch(PDO::FETCH_ASSOC);
        return $r ?: null;
    }

    /**
     * Grant path for the affiliate add-on (DwStore::grantInvoice does not know this entitlement
     * on production, and skips it).
     * Idempotent on source_invoice_product_id. Never creates a subscription.
     */
    public static function grantEntitlementFromInvoice(PDO $db, string $invoiceId): int
    {
        // Paid invoice of an attributed subscription: commission ledger (see onInvoicePaid). Never blocks the grant.
        try {
            self::onInvoicePaid($db, $invoiceId);
        } catch (Throwable $e) {
            error_log('affiliate commission failed: ' . get_class($e));
        }
        $granted = 0;
        $i = $db->prepare('SELECT brand, person_id, paypal_subscription_id FROM invoice WHERE id = ?');
        $i->execute([$invoiceId]);
        $inv = $i->fetch(PDO::FETCH_ASSOC);
        if (!is_array($inv)) {
            return 0;
        }
        $lines = $db->prepare(
            "SELECT ip.id, ip.variant_id, ip.quantity, ip.target_domain_id, p.entitlements,
                    v.billing_interval, v.billing_interval_count, d.code AS target_brand
               FROM invoice_product ip
               JOIN product p ON p.id = ip.product_id
               JOIN product_variant v ON v.id = ip.variant_id
               LEFT JOIN domain d ON d.id = ip.target_domain_id
              WHERE ip.invoice_id = ? AND p.entitlements IS NOT NULL AND p.entitlements <> ''"
        );
        $lines->execute([$invoiceId]);
        foreach ($lines->fetchAll(PDO::FETCH_ASSOC) as $l) {
            $ents = array_map('trim', explode(',', (string)$l['entitlements']));
            if (!in_array(self::GATE_FEATURE, $ents, true)) {
                continue;
            }
            if ($l['target_brand'] === null || !in_array((string)$l['billing_interval'], ['MONTH', 'YEAR'], true)) {
                continue;
            }
            $have = $db->prepare('SELECT id, status FROM brand_entitlement WHERE source_invoice_product_id = ? LIMIT 1');
            $have->execute([$l['id']]);
            $row = $have->fetch(PDO::FETCH_ASSOC);
            if (is_array($row)) {
                if (($row['status'] ?? '') === 'REVOKED') {
                    $db->prepare("UPDATE brand_entitlement SET status = 'ACTIVE', note = 'payment completed again', updated = NOW() WHERE id = ?")
                        ->execute([$row['id']]);
                    $granted++;
                }
                continue;
            }
            $n = max(1, (int)$l['quantity'] * max(1, (int)$l['billing_interval_count']));
            $unit = strtoupper((string)$l['billing_interval']) === 'YEAR' ? 'YEAR' : 'MONTH';
            $id = Dw::randId();
            $sql = "INSERT INTO brand_entitlement
                    (id, brand, domain_id, entitlement, status, starts_at, paid_through, grace_until,
                     source_brand, source_invoice_id, source_invoice_product_id, source_variant_id,
                     provider_ref, provider_status, created, created_by_person_id, updated, updated_by_person_id)
                    VALUES (?, ?, ?, ?, 'ACTIVE', NOW(), DATE_ADD(NOW(), INTERVAL {$n} {$unit}), DATE_ADD(DATE_ADD(NOW(), INTERVAL {$n} {$unit}), INTERVAL 3 DAY),
                            ?, ?, ?, ?, ?, ?, NOW(), ?, NOW(), ?)";
            $sid = $inv['paypal_subscription_id'] ?? null;
            $by = $inv['person_id'] ?? null;
            $db->prepare($sql)->execute([
                $id,
                $l['target_brand'],
                $l['target_domain_id'],
                self::GATE_FEATURE,
                $inv['brand'],
                $invoiceId,
                $l['id'],
                $l['variant_id'],
                $sid,
                $sid ? 'ACTIVE' : null,
                $by,
                $by,
            ]);
            try {
                Dw::history($db, 'brand_entitlement', $id, 'INSERT');
            } catch (Throwable $e) {
            }
            $granted++;
        }
        return $granted;
    }

    public static function canManage(PDO $db, string $personId, string $brand): bool
    {
        $q = $db->prepare("SELECT 1 FROM data_access WHERE person_id = ? AND brand = ? AND right_name = 'SUPER_ADMIN' LIMIT 1");
        $q->execute([$personId, $brand]);
        if ($q->fetchColumn() !== false) {
            return true;
        }
        $in = implode(',', array_fill(0, count(self::MANAGE_RIGHTS), '?'));
        $q = $db->prepare(
            "SELECT 1 FROM data_access
              WHERE person_id = ? AND brand = ? AND module_name = ? AND right_name IN ($in)
              LIMIT 1"
        );
        $q->execute(array_merge([$personId, $brand, self::MODULE], self::MANAGE_RIGHTS));
        return $q->fetchColumn() !== false;
    }

    public static function listManagers(PDO $db, string $brand): array
    {
        $q = $db->prepare(
            "SELECT DISTINCT e.email, p.first_name, p.last_name FROM data_access d
             JOIN person p ON p.id = d.person_id
             JOIN email e ON e.owner_id = p.id AND e.owner_type = 'PRSN' AND e.brand = d.brand
             WHERE d.brand = ? AND d.module_name = ?
             ORDER BY e.email"
        );
        $q->execute([$brand, self::MODULE]);
        $out = [];
        $seen = [];
        foreach ($q->fetchAll(PDO::FETCH_ASSOC) as $row) {
            $em = strtolower((string)$row['email']);
            if ($em === '' || isset($seen[$em])) {
                continue;
            }
            $seen[$em] = true;
            $name = trim((string)($row['first_name'] ?? '') . ' ' . (string)($row['last_name'] ?? ''));
            $out[] = ['email' => $em, 'name' => $name];
        }
        return $out;
    }

    /**
     * @return array{ok:bool,existed:bool,person_id:?string}
     */
    public static function grantManager(PDO $db, string $personId, string $brand, string $by): array
    {
        $own = !$db->inTransaction();
        if ($own) {
            $db->beginTransaction();
        }
        try {
            $ex = $db->prepare(
                'SELECT id FROM data_access WHERE person_id = ? AND brand = ? AND module_name = ? LIMIT 1'
            );
            $ex->execute([$personId, $brand, self::MODULE]);
            if ($ex->fetchColumn() !== false) {
                if ($own) {
                    $db->commit();
                }
                return ['ok' => true, 'existed' => true, 'person_id' => $personId];
            }
            $ins = $db->prepare(
                'INSERT INTO data_access (id, person_id, brand, created, created_by_person_id, right_name, module_name)
                 VALUES (?, ?, ?, NOW(), ?, ?, ?)'
            );
            $hist = $db->prepare(
                "INSERT INTO data_access_history (history_id, id, person_id, brand, created, created_by_person_id, right_name, module_name, action, archived_at)
                 VALUES (?, ?, ?, ?, NOW(), ?, ?, ?, 'INSERT', NOW())"
            );
            foreach (self::MANAGE_RIGHTS as $right) {
                $id = Dw::randId();
                $ins->execute([$id, $personId, $brand, $by, $right, self::MODULE]);
                $hist->execute([Dw::randId(), $id, $personId, $brand, $by, $right, self::MODULE]);
            }
            if (method_exists('Dw', 'refreshSessionRights')) {
                Dw::refreshSessionRights($db, $personId, $brand);
            }
            if ($own) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($own && $db->inTransaction()) {
                $db->rollBack();
            }
            throw $e;
        }
        return ['ok' => true, 'existed' => false, 'person_id' => $personId];
    }

    /**
     * @return array{ok:bool,existed:bool,revoked:bool,person_id:?string}
     */
    public static function revokeManager(PDO $db, string $personId, string $brand): array
    {
        $own = !$db->inTransaction();
        if ($own) {
            $db->beginTransaction();
        }
        try {
            $ex = $db->prepare(
                'SELECT id FROM data_access WHERE person_id = ? AND brand = ? AND module_name = ? FOR UPDATE'
            );
            $ex->execute([$personId, $brand, self::MODULE]);
            $rows = $ex->fetchAll(PDO::FETCH_COLUMN);
            if ($rows === []) {
                if ($own) {
                    $db->commit();
                }
                return ['ok' => true, 'existed' => false, 'revoked' => false, 'person_id' => $personId];
            }
            $hist = $db->prepare(
                "INSERT INTO data_access_history (history_id, id, person_id, brand, created, created_by_person_id, right_name, module_name, action, archived_at)
                 SELECT ?, id, person_id, brand, created, created_by_person_id, right_name, module_name, 'DELETE', NOW()
                   FROM data_access WHERE id = ?"
            );
            $del = $db->prepare('DELETE FROM data_access WHERE id = ?');
            foreach ($rows as $rid) {
                $hist->execute([Dw::randId(), $rid]);
                $del->execute([$rid]);
            }
            if (method_exists('Dw', 'refreshSessionRights')) {
                Dw::refreshSessionRights($db, $personId, $brand);
            }
            if ($own) {
                $db->commit();
            }
        } catch (Throwable $e) {
            if ($own && $db->inTransaction()) {
                $db->rollBack();
            }
            throw $e;
        }
        return ['ok' => true, 'existed' => true, 'revoked' => true, 'person_id' => $personId];
    }

}

class DwAffiliateLimit extends RuntimeException
{
    /** @var array<string,mixed> */
    public array $gate;

    /** @param array<string,mixed> $gate */
    public function __construct(string $message, array $gate = [])
    {
        parent::__construct($message);
        $this->gate = $gate;
    }
}
